                try(PreparedStatement q=query(c,"SELECT m.name,count(*) AS score FROM events e JOIN members m ON m.id=e.member_id WHERE m.active AND e.received_at>=? AND e.received_at<? AND e.type=? AND e.event_key=? GROUP BY m.id,m.name ORDER BY score DESC,m.normalized_name,m.id LIMIT 1000",r.getTimestamp(4),r.getTimestamp(5),r.getString(6),r.getString(7));ResultSet rows=q.executeQuery()) {
                    int place=0;while(rows.next()){JsonObject row=new JsonObject();row.addProperty("name",rows.getString(1));row.addProperty("score",rows.getLong(2));
                        row.addProperty("projectedPoints",prizes.getOrDefault(++place,0));standings.add(row);}
                }
                race.add("standings",standings);JsonArray firsts=new JsonArray();
                try(PreparedStatement q=query(c,"SELECT label,event_type,event_key,points FROM race_firsts WHERE race_id=? ORDER BY label,id LIMIT 50",id);ResultSet rows=q.executeQuery()) {
                    while(rows.next()){JsonObject first=new JsonObject();first.addProperty("label",rows.getString(1));first.addProperty("points",rows.getInt(4));
                        try(PreparedStatement winner=query(c,"SELECT m.name FROM events e JOIN members m ON m.id=e.member_id WHERE m.active AND e.received_at>=? AND e.received_at<? AND e.type=? AND e.event_key=? ORDER BY e.received_at,e.id LIMIT 1",r.getTimestamp(4),r.getTimestamp(5),rows.getString(2),rows.getString(3));ResultSet found=winner.executeQuery()){first.addProperty("winner",found.next()?found.getString(1):"Unclaimed");}firsts.add(first);}
                }
                race.add("firsts",firsts);races.add(race);
            }
        }
        return races;
    }
}

package com.traphouse.server;

import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.sql.*;

/** Retry the complete additive initialization transaction when live traffic conflicts with DDL. */
final class DatabaseInitialization {
    interface Migration {void apply(Connection c)throws Exception;}
    static void run(DiscordWorker.Connections connections)throws Exception {run(connections,DatabaseInitialization::apply);}
    static void run(DiscordWorker.Connections connections,Migration migration)throws Exception {
        for(int attempt=1;;attempt++) {
            try(Connection c=connections.open()) {
                c.setAutoCommit(false);
                try {
                    RankingStore.execute(c,"SET LOCAL lock_timeout='5s'");
                    migration.apply(c);c.commit();return;
                }catch(Exception failure) {
                    try{c.rollback();}catch(SQLException rollback){failure.addSuppressed(rollback);}
                    throw failure;
                }
            }catch(SQLException conflict) {
                if(attempt>=5||!retryable(conflict))throw conflict;
                System.err.println("Database initialization encountered temporary lock contention (SQLSTATE "+conflict.getSQLState()+"); retrying transaction "+(attempt+1)+"/5.");
                Thread.sleep(250L<<(attempt-1));
            }
        }
    }
    static boolean retryable(SQLException error){return "40P01".equals(error.getSQLState())||"55P03".equals(error.getSQLState())||"40001".equals(error.getSQLState());}
    private static void script(Connection c,String resource)throws Exception {
        try(InputStream input=RankingServer.class.getResourceAsStream(resource);Statement s=c.createStatement()) {
            if(input==null)throw new IllegalStateException("Initialization resource missing: "+resource);
            s.execute(new String(input.readAllBytes(),StandardCharsets.UTF_8));
        }
    }
    static void apply(Connection c)throws Exception {
        script(c,"/schema.sql");script(c,"/starter-goals.sql");script(c,"/rank-thresholds-v1.sql");
        MilestoneCatalog.seed(c);MilestoneCatalog.applyRewards(c);MilestoneCatalog.applyRewardBoost(c);MilestoneCatalog.applyCurrentRewards(c);
        script(c,"/activity-rewards-v3.sql");AutomaticRewards.seed(c);BalancedRewards.apply(c);RankManagement.initializeOwnerRanks(c);script(c,"/discord-joining.sql");
        script(c,"/achievement-diaries.sql");
    }
}

package com.traphouse.server;

import com.google.gson.*;
import com.sun.net.httpserver.HttpExchange;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.security.*;
import java.security.spec.X509EncodedKeySpec;
import java.sql.*;
import java.time.Instant;
import java.util.*;

/** Public endpoint: verify Discord Ed25519 signatures over the exact raw request bytes. */
final class DiscordInteractions {
    private final DiscordWorker.Connections connections;
    private final Map<String,String> env;
    DiscordInteractions(DiscordWorker.Connections connections,Map<String,String> env){this.connections=connections;this.env=env;}
    static byte[] hex(String value) {
        if(value==null||value.length()%2!=0||!value.matches("[0-9a-fA-F]+"))throw new IllegalArgumentException("Invalid hex");
        byte[] out=new byte[value.length()/2];for(int i=0;i<out.length;i++)out[i]=(byte)Integer.parseInt(value.substring(i*2,i*2+2),16);return out;
    }
    static boolean verify(String key,String signature,String timestamp,byte[] body,Instant now) {
        try {
            if(key==null||key.length()!=64||signature==null||signature.length()!=128||timestamp==null||!timestamp.matches("[0-9]{10}"))return false;
            if(Math.abs(now.getEpochSecond()-Long.parseLong(timestamp))>300)return false;
            byte[] prefix=hex("302a300506032b6570032100"),raw=hex(key),encoded=Arrays.copyOf(prefix,prefix.length+raw.length);System.arraycopy(raw,0,encoded,prefix.length,raw.length);
            Signature verifier=Signature.getInstance("Ed25519");verifier.initVerify(KeyFactory.getInstance("Ed25519").generatePublic(new X509EncodedKeySpec(encoded)));
            verifier.update(timestamp.getBytes(StandardCharsets.UTF_8));verifier.update(body);return verifier.verify(hex(signature));
        }catch(Exception invalid){return false;}
    }
    void handle(HttpExchange exchange)throws IOException {
        int status=200;JsonObject response;
        try {
            if(!exchange.getRequestMethod().equals("POST"))throw new Policy.Rejected(405,"Use POST");
            String publicKey=env.get("TRAP_DISCORD_PUBLIC_KEY");
            if(publicKey==null||!publicKey.matches("[0-9a-fA-F]{64}"))throw new Policy.Rejected(503,"Discord interactions are not configured");
            byte[] body=exchange.getRequestBody().readNBytes(16385);if(body.length>16384)throw new Policy.Rejected(413,"Request too large");
            if(!verify(publicKey,exchange.getRequestHeaders().getFirst("X-Signature-Ed25519"),exchange.getRequestHeaders().getFirst("X-Signature-Timestamp"),body,Instant.now()))throw new Policy.Rejected(401,"Invalid Discord signature");
            JsonObject interaction=JsonParser.parseString(new String(body,StandardCharsets.UTF_8)).getAsJsonObject();
            if(!Objects.equals(env.get("TRAP_DISCORD_CLIENT_ID"),Policy.text(interaction,"application_id",20)))throw new Policy.Rejected(403,"Wrong Discord application");
            if(interaction.get("type").getAsInt()==1){response=new JsonObject();response.addProperty("type",1);}
            else {
                if(!Objects.equals(env.get("TRAP_DISCORD_GUILD_ID"),Policy.text(interaction,"guild_id",20)))throw new Policy.Rejected(403,"Use this action inside the configured clan Discord server");
                String discord=DiscordLogin.snowflake(Policy.text(interaction.getAsJsonObject("member").getAsJsonObject("user"),"id",20));
                String id=DiscordLogin.snowflake(Policy.text(interaction,"id",20));
                try(Connection c=connections.open()) {
                    c.setAutoCommit(false);
                    try {
                        RankingStore.execute(c,"SET LOCAL statement_timeout='2s'");RankingStore.execute(c,"SET LOCAL lock_timeout='1s'");
                        // Response caching makes Discord retries idempotent, including modal submits.
                        int inserted;
                        try(PreparedStatement s=RankingStore.query(c,"INSERT INTO discord_interactions(id,response) VALUES (?,'{}') ON CONFLICT DO NOTHING",id)){inserted=s.executeUpdate();}
                        if(inserted==0) {
                            try(PreparedStatement s=RankingStore.query(c,"SELECT response::text FROM discord_interactions WHERE id=?",id);ResultSet r=s.executeQuery()){r.next();response=DiscordJoining.object(r.getString(1));}
                        } else {
                            Savepoint operation=c.setSavepoint();
                            try {response=DiscordJoining.dispatch(c,interaction,discord,env.get("TRAP_DISCORD_STAFF_ROLE_ID"));}
                            catch(Policy.Rejected rejected){c.rollback(operation);response=DiscordJoining.message(rejected.getMessage());}
                            RankingStore.execute(c,"UPDATE discord_interactions SET response=?::jsonb WHERE id=?",response.toString(),id);
                        }
                        c.commit();
                    }catch(Exception failure){c.rollback();throw failure;}
                }
            }
        }catch(Policy.Rejected rejected){status=rejected.status;response=new JsonObject();response.addProperty("error",rejected.getMessage());}
        catch(JsonParseException|IllegalArgumentException|NullPointerException invalid){status=400;response=DiscordJoining.object("{\"error\":\"Invalid Discord request\"}");}
        catch(Exception unavailable){response=DiscordJoining.message("Linking is temporarily unavailable. No partial approval was saved. Please retry shortly.");}
        byte[] bytes=response.toString().getBytes(StandardCharsets.UTF_8);exchange.getResponseHeaders().set("Content-Type","application/json; charset=utf-8");exchange.getResponseHeaders().set("Cache-Control","no-store");
        exchange.sendResponseHeaders(status,bytes.length);try(OutputStream out=exchange.getResponseBody()){out.write(bytes);}finally{exchange.close();}
    }
}

package com.traphouse.server;

import com.google.gson.*;
import java.sql.*;
import java.util.*;
import static com.traphouse.server.RankingStore.*;

/** Log a resolved request durably before deleting its public review message. */
final class DiscordJoinArchive {
    static void enqueue(Connection c,UUID request)throws SQLException {
        try(PreparedStatement s=query(c,"SELECT r.character_name,r.discord_user_id,r.status,r.reason,coalesce(r.reviewer_discord_id,m.name),r.reviewed_at FROM discord_join_requests r LEFT JOIN members m ON m.id=r.reviewer WHERE r.id=? AND r.status<>'PENDING'",request);ResultSet r=s.executeQuery()) {
            if(!r.next())return;
            JsonObject payload=new JsonObject();
            payload.addProperty("content","**RuneLite link "+r.getString(3).toLowerCase(Locale.ROOT)+"**\nCharacter: **"+r.getString(1)+"**\nDiscord ID: `"+r.getString(2)+"`\nReviewed by: **"+r.getString(5)+"**\nReason: "+plain(r.getString(4))+"\nReviewed: "+r.getTimestamp(6).toInstant()+"\nRequest: `"+request+"`");
            payload.add("allowed_mentions",DiscordJoining.object("{\"parse\":[]}"));
            payload.addProperty("nonce",request.toString().replace("-","").substring(0,24));payload.addProperty("enforce_nonce",true);
            execute(c,"INSERT INTO discord_join_archive_outbox(request_id,payload) VALUES (?,?::jsonb) ON CONFLICT DO NOTHING",request,payload.toString());
        }
    }
    private static String plain(String value){return value==null?"":value.replaceAll("[\\p{Cntrl}`*_~<>]"," ").trim();}
    static void remember(Connection c,JsonObject interaction,UUID request)throws SQLException {
        // /pending is ephemeral and contains several requests; never delete that message.
        if(!interaction.has("message")||!interaction.has("channel_id")||!interaction.has("application_id"))return;
        JsonObject message=interaction.getAsJsonObject("message");
        if(message.has("flags")&&(message.get("flags").getAsInt()&64)!=0)return;
        if(!message.has("author")||!interaction.get("application_id").getAsString().equals(message.getAsJsonObject("author").get("id").getAsString()))return;
        remember(c,request,DiscordLogin.snowflake(Policy.text(interaction,"channel_id",20)),DiscordLogin.snowflake(Policy.text(message,"id",20)));
    }
    static void remember(Connection c,UUID request,String channel,String message)throws SQLException {
        execute(c,"UPDATE discord_join_outbox SET review_channel_id=?,review_message_id=? WHERE id=? AND review_message_id IS NULL",channel,message,request);
    }
    static void deliver(Connection c,Map<String,String> env,DiscordJoinBot.Transport transport)throws SQLException {
        try(PreparedStatement s=query(c,"SELECT request_id,payload::text,logged_at,attempts FROM discord_join_archive_outbox WHERE cleaned_at IS NULL AND next_attempt<=now() ORDER BY created_at,request_id LIMIT 1 FOR UPDATE SKIP LOCKED");ResultSet r=s.executeQuery()) {
            if(!r.next())return;UUID id=r.getObject(1,UUID.class);
            try {
                if(r.getTimestamp(3)==null) {
                    String channel=DiscordLogin.snowflake(env.get("TRAP_DISCORD_STAFF_LOG_CHANNEL_ID"));
                    if(channel.equals(env.get("TRAP_DISCORD_REVIEW_CHANNEL_ID")))throw new IllegalArgumentException("Staff log must be separate from the review channel");
                    DiscordJoinBot.Reply reply=transport.send("POST","channels/"+channel+"/messages",DiscordJoining.object(r.getString(2)));
                    if(reply.status<200||reply.status>=300)throw new IllegalStateException("Staff log unavailable");
                    String message=DiscordLogin.snowflake(Policy.text(DiscordJoining.object(reply.body),"id",20));
                    execute(c,"UPDATE discord_join_archive_outbox SET staff_channel_id=?,staff_message_id=?,logged_at=now(),attempts=0,next_attempt=now() WHERE request_id=?",channel,message,id);
                    // Commit the log receipt separately. Cleanup cannot run before this is durable.
                    return;
                }
                try(PreparedStatement q=query(c,"SELECT review_channel_id,review_message_id,delivered_at FROM discord_join_outbox WHERE id=? FOR UPDATE",id);ResultSet pending=q.executeQuery()) {
                    if(pending.next()) {
                        if(pending.getTimestamp(3)==null)return;
                        if(pending.getString(2)!=null) {
                            String channel=DiscordLogin.snowflake(pending.getString(1)),message=DiscordLogin.snowflake(pending.getString(2));
                            int status=transport.send("DELETE","channels/"+channel+"/messages/"+message,new JsonObject()).status;
                            if(status!=404&&(status<200||status>=300))throw new IllegalStateException("Review cleanup unavailable");
                        }
                    }
                }
                execute(c,"UPDATE discord_join_archive_outbox SET cleaned_at=now(),attempts=attempts+1 WHERE request_id=?",id);
            }catch(InterruptedException interrupted){Thread.currentThread().interrupt();}
            catch(Exception retry){execute(c,"UPDATE discord_join_archive_outbox SET attempts=attempts+1,next_attempt=now()+(? * interval '1 second') WHERE request_id=?",Math.min(3600,60L<<Math.min(r.getInt(4),6)),id);}
        }
    }
}

package com.traphouse.server;

import com.google.gson.*;
import java.net.URI;
import java.net.http.*;
import java.sql.*;
import java.time.Duration;
import java.util.*;

/** Bot channel messages use a separate durable outbox; interaction handlers never wait on HTTP. */
final class DiscordJoinBot implements Runnable {
    private final DiscordWorker.Connections connections;
    private final Map<String,String> env;
    private final HttpClient http=HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(5)).followRedirects(HttpClient.Redirect.NEVER).build();
    interface Transport {Reply send(String method,String path,JsonObject body)throws Exception;}
    static final class Reply {final int status;final String body;Reply(int status,String body){this.status=status;this.body=body;}}
    private final Transport transport;
    DiscordJoinBot(DiscordWorker.Connections connections,Map<String,String> env){this.connections=connections;this.env=env;this.transport=this::exchange;}
    DiscordJoinBot(DiscordWorker.Connections connections,Map<String,String> env,Transport transport){this.connections=connections;this.env=env;this.transport=transport;}
    private String required(String key) {String v=env.get(key);if(v==null||v.isBlank())throw new IllegalArgumentException("Configure "+key+" in Render");return v;}
    private Reply exchange(String method,String path,JsonObject body)throws Exception {
        HttpRequest request=HttpRequest.newBuilder(URI.create("https://discord.com/api/v10/"+path)).timeout(Duration.ofSeconds(10)).header("Authorization","Bot "+required("TRAP_DISCORD_BOT_TOKEN"))
            .header("Content-Type","application/json").method(method,method.equals("GET")||method.equals("DELETE")?HttpRequest.BodyPublishers.noBody():HttpRequest.BodyPublishers.ofString(body.toString())).build();
        HttpResponse<String> response=http.send(request,HttpResponse.BodyHandlers.ofString());return new Reply(response.statusCode(),response.body());
    }
    private int send(String method,String path,JsonObject body)throws Exception{return transport.send(method,path,body).status;}
    static JsonObject command(String name) {
        JsonObject body=new JsonObject();body.addProperty("name",name);body.addProperty("type",1);
        switch(name) {
            case "link":body.addProperty("description","Request a verified RuneLite character link");break;
            case "pending":body.addProperty("description","Staff: review pending RuneLite character links");break;
            case "edit-link":body.addProperty("description","Owner: correct an accepted RuneLite link's character name");break;
            case "revoke-link":body.addProperty("description","Owner: revoke an accepted RuneLite link and its credentials");break;
            default:throw new IllegalArgumentException("Unknown link command");
        }
        if(name.equals("edit-link")||name.equals("revoke-link")) {
            JsonObject member=new JsonObject();member.addProperty("type",6);member.addProperty("name","member");
            member.addProperty("description","Discord member whose accepted link you want to manage");member.addProperty("required",true);
            JsonArray options=new JsonArray();options.add(member);body.add("options",options);
        }
        return body;
    }
    void setup()throws Exception {setup(true);}
    int cleanReviewedMessages()throws Exception {
        String channel=DiscordLogin.snowflake(required("TRAP_DISCORD_REVIEW_CHANNEL_ID")),app=DiscordLogin.snowflake(required("TRAP_DISCORD_CLIENT_ID"));
        String staff=DiscordLogin.snowflake(required("TRAP_DISCORD_STAFF_LOG_CHANNEL_ID"));
        if(channel.equals(staff))throw new IllegalArgumentException("Staff log must be separate from the review channel");
        String before="";int queued=0;
        try(Connection c=connections.open()) {
            c.setAutoCommit(false);
            // Bounded historical cleanup; never touch unrelated or still-pending messages.
            for(int page=0;page<10;page++) {
                Reply reply=transport.send("GET","channels/"+channel+"/messages?limit=100"+before,new JsonObject());
                if(reply.status<200||reply.status>=300)throw new IllegalStateException("Cannot read review channel (HTTP "+reply.status+")");
                JsonArray messages=JsonParser.parseString(reply.body).getAsJsonArray();
                if(messages.size()==0)break;
                for(JsonElement value:messages) {
                    JsonObject message=value.getAsJsonObject();
                    if(!message.has("author")||!app.equals(message.getAsJsonObject("author").get("id").getAsString()))continue;
                    UUID request=reviewRequest(message);if(request==null)continue;
                    try(PreparedStatement s=RankingStore.query(c,"SELECT 1 FROM discord_join_requests WHERE id=? AND status<>'PENDING'",request);ResultSet r=s.executeQuery()) {
                        if(!r.next())continue;
                        DiscordJoinArchive.enqueue(c,request);DiscordJoinArchive.remember(c,request,channel,DiscordLogin.snowflake(Policy.text(message,"id",20)));queued++;
                    }
                }
                c.commit();before="&before="+DiscordLogin.snowflake(Policy.text(messages.get(messages.size()-1).getAsJsonObject(),"id",20));
                if(messages.size()<100)break;
            }
        }
        return queued;
    }
    static UUID reviewRequest(JsonObject message) {
        if(!message.has("components"))return null;
        for(JsonElement row:message.getAsJsonArray("components")) {
            JsonObject group=row.getAsJsonObject();if(!group.has("components"))continue;
            for(JsonElement value:group.getAsJsonArray("components")) {
                JsonObject button=value.getAsJsonObject();if(!button.has("custom_id"))continue;
                String custom=button.get("custom_id").getAsString();
                if(custom.matches("join:(approve|reject):[0-9a-fA-F-]{36}")) {
                    try{return UUID.fromString(custom.substring(custom.lastIndexOf(':')+1));}catch(IllegalArgumentException invalid){return null;}
                }
            }
        }
        return null;
    }
    void setup(boolean postButton)throws Exception {
        String app=DiscordLogin.snowflake(required("TRAP_DISCORD_CLIENT_ID")),guild=DiscordLogin.snowflake(required("TRAP_DISCORD_GUILD_ID"));
        String channel=DiscordLogin.snowflake(required("TRAP_DISCORD_LINK_CHANNEL_ID"));DiscordLogin.snowflake(required("TRAP_DISCORD_REVIEW_CHANNEL_ID"));
        if(!required("TRAP_DISCORD_PUBLIC_KEY").matches("[0-9a-fA-F]{64}"))throw new IllegalArgumentException("Use the Discord application's 64-character Public Key");
        required("TRAP_DISCORD_BOT_TOKEN");
        try(Connection c=connections.open();PreparedStatement s=RankingStore.query(c,"SELECT 1 FROM discord_member_links l JOIN members m ON m.id=l.member_id JOIN member_permissions p ON p.member_id=m.id WHERE m.active AND p.permission='OWNER' LIMIT 1");ResultSet r=s.executeQuery()) {
            if(!r.next())throw new IllegalStateException("Link and bootstrap the verified clan Owner before setting up Discord approvals. See docs/discord-joining.md.");
        }
        for(String command:new String[]{"link","pending","edit-link","revoke-link"}) {
            JsonObject body=command(command);
            // Upsert only our commands; do not replace unrelated application commands.
            int status=send("POST","applications/"+app+"/guilds/"+guild+"/commands",body);
            if(status<200||status>=300)throw new IllegalStateException("Discord command setup failed (HTTP "+status+")");
        }
        if(!postButton)return;
        JsonObject body=new JsonObject();body.addProperty("content","**TRAP HOUSE RuneLite linking**\nClick Link RuneLite and enter your OSRS name. Staff must verify your character and clan membership before approval. After approval, use Sign in with Discord in the plugin.");
        body.add("allowed_mentions",DiscordJoining.object("{\"parse\":[]}"));JsonArray rows=new JsonArray();rows.add(DiscordJoining.row(DiscordJoining.button("join:start","Link RuneLite",1)));body.add("components",rows);
        int status=send("POST","channels/"+channel+"/messages",body);if(status<200||status>=300)throw new IllegalStateException("Discord link button failed (HTTP "+status+")");
    }
    @Override public void run() {
        try(Connection c=connections.open()) {
            c.setAutoCommit(false);
            // Signatures expire after five minutes; a day of cached responses covers retries.
            RankingStore.execute(c,"DELETE FROM discord_interactions WHERE created_at<now()-interval '1 day'");
            try(PreparedStatement s=RankingStore.query(c,"SELECT id,payload::text,attempts FROM discord_join_outbox WHERE delivered_at IS NULL AND next_attempt<=now() ORDER BY created_at LIMIT 1 FOR UPDATE SKIP LOCKED");ResultSet r=s.executeQuery()) {
                if(!r.next()){DiscordJoinArchive.deliver(c,env,transport);c.commit();return;}
                UUID id=r.getObject(1,UUID.class);boolean delivered=false;
                try {
                    String state=null;
                    try(PreparedStatement q=RankingStore.query(c,"SELECT status FROM discord_join_requests WHERE id=?",id);ResultSet request=q.executeQuery()){if(request.next())state=request.getString(1);}
                    if(!"PENDING".equals(state))delivered=true;
                    else {
                        String channel=DiscordLogin.snowflake(required("TRAP_DISCORD_REVIEW_CHANNEL_ID"));
                        JsonObject payload=DiscordJoining.object(r.getString(2));payload.addProperty("nonce",id.toString().replace("-","").substring(0,24));payload.addProperty("enforce_nonce",true);
                        Reply response=transport.send("POST","channels/"+channel+"/messages",payload);
                        if(response.status>=200&&response.status<300) {
                            String message=DiscordLogin.snowflake(Policy.text(DiscordJoining.object(response.body),"id",20));
                            RankingStore.execute(c,"UPDATE discord_join_outbox SET review_channel_id=?,review_message_id=? WHERE id=?",channel,message,id);delivered=true;
                        }
                    }
                }
                catch(InterruptedException interrupted){Thread.currentThread().interrupt();return;}
                catch(Exception retry){/* Never log the bot token, request headers, or response bodies. */}
                if(delivered)RankingStore.execute(c,"UPDATE discord_join_outbox SET delivered_at=now(),attempts=attempts+1 WHERE id=?",id);
                else RankingStore.execute(c,"UPDATE discord_join_outbox SET attempts=attempts+1,next_attempt=now()+(? * interval '1 second') WHERE id=?",Math.min(3600,60L<<Math.min(r.getInt(3),6)),id);
                c.commit();
            }
            DiscordJoinArchive.deliver(c,env,transport);c.commit();
        }catch(SQLException failure){System.err.println("Discord linking notifications unavailable; will retry.");}
    }
}

package com.traphouse.server;

import com.google.gson.*;
import java.sql.*;
import java.util.*;

/** Signed Discord identities may request links. The Owner or configured staff role reviews them. */
final class DiscordJoining {
    static String characterName(String value) {
        if(value==null||!value.matches("[A-Za-z0-9 _-]{1,12}")||value.trim().isEmpty())throw new Policy.Rejected(400,"Enter a valid OSRS character name (1–12 characters).");
        return value.trim();
    }
    static JsonObject object(String json){return JsonParser.parseString(json).getAsJsonObject();}
    static JsonObject message(String content) {
        JsonObject data=new JsonObject();data.addProperty("content",content);data.addProperty("flags",64);
        data.add("allowed_mentions",object("{\"parse\":[]}"));JsonObject reply=new JsonObject();reply.addProperty("type",4);reply.add("data",data);return reply;
    }
    static JsonObject button(String id,String label,int style) {
        JsonObject button=new JsonObject();button.addProperty("type",2);button.addProperty("style",style);button.addProperty("custom_id",id);button.addProperty("label",label);return button;
    }
    static JsonObject row(JsonObject... buttons) {
        JsonObject row=new JsonObject();row.addProperty("type",1);JsonArray components=new JsonArray();for(JsonObject b:buttons)components.add(b);row.add("components",components);return row;
    }
    static JsonObject modal(String id,String title,String field,String label,int max) {
        JsonObject input=new JsonObject();input.addProperty("type",4);input.addProperty("custom_id",field);input.addProperty("label",label);
        input.addProperty("style",field.equals("reason")?2:1);input.addProperty("required",true);input.addProperty("max_length",max);
        JsonArray rows=new JsonArray();rows.add(row(input));JsonObject data=new JsonObject();data.addProperty("custom_id",id);data.addProperty("title",title);data.add("components",rows);
        JsonObject response=new JsonObject();response.addProperty("type",9);response.add("data",data);return response;
    }
    static String field(JsonObject data,String key,int max) {
        String value=null;
        for(JsonElement row:data.getAsJsonArray("components"))for(JsonElement element:row.getAsJsonObject().getAsJsonArray("components")) {
            JsonObject input=element.getAsJsonObject();
            if(key.equals(Policy.text(input,"custom_id",100))) {if(value!=null)throw new Policy.Rejected(400,"Duplicate form field");value=Policy.text(input,"value",max);}
        }
        if(value==null)throw new Policy.Rejected(400,"Missing form field");return value;
    }
    static RankingStore.Actor owner(Connection c,String discord)throws SQLException {
        try(PreparedStatement s=RankingStore.query(c,"SELECT m.id,m.name FROM discord_member_links l JOIN members m ON m.id=l.member_id JOIN member_permissions p ON p.member_id=m.id WHERE l.discord_user_id=? AND m.active AND p.permission='OWNER' FOR UPDATE OF m,p",discord);ResultSet r=s.executeQuery()) {
            if(!r.next())throw new Policy.Rejected(403,"Only the linked clan Owner can review membership requests.");
            RankingStore.Actor owner=new RankingStore.Actor(r.getObject(1,UUID.class),r.getString(2),RankSecurity.Role.OWNER);
            // Serialize decisions and permission changes against the member row.
            RankingStore.lockMember(c,owner.id);return owner;
        }
    }
    static boolean staff(JsonObject interaction,String role) {
        if(role==null||!role.matches("[0-9]{17,20}"))return false;
        JsonObject member=interaction.getAsJsonObject("member");
        if(member==null||!member.has("roles")||!member.get("roles").isJsonArray())return false;
        for(JsonElement value:member.getAsJsonArray("roles"))
            if(value.isJsonPrimitive()&&value.getAsJsonPrimitive().isString()&&role.equals(value.getAsString()))return true;
        return false;
    }
    static UUID reviewer(Connection c,String discord,boolean staff)throws SQLException {
        if(!staff)return owner(c,discord).id;
        try(PreparedStatement s=RankingStore.query(c,"SELECT member_id FROM discord_member_links WHERE discord_user_id=?",discord);ResultSet r=s.executeQuery()) {
            return r.next()?r.getObject(1,UUID.class):null;
        }
    }
    static JsonObject decisions(UUID id) {return row(button("join:approve:"+id,"Approve after verification",3),button("join:reject:"+id,"Reject",4));}
    static JsonObject linkForm(Connection c,String discord)throws SQLException {
        try(PreparedStatement s=RankingStore.query(c,"SELECT m.name,m.active FROM discord_member_links l JOIN members m ON m.id=l.member_id WHERE l.discord_user_id=?",discord);ResultSet r=s.executeQuery()) {
            if(r.next())return message(r.getBoolean(2)?"Your account is linked to "+r.getString(1)+". Click Sign in with Discord in RuneLite to connect.":"Your linked clan membership is inactive. Contact the Owner.");
        }
        try(PreparedStatement s=RankingStore.query(c,"SELECT character_name FROM discord_join_requests WHERE discord_user_id=? AND status='PENDING'",discord);ResultSet r=s.executeQuery()) {
            if(r.next())return message("Your request for "+r.getString(1)+" is waiting for staff to verify and approve it. No access has been granted yet.");
        }
        return modal("join:request","Link RuneLite","rsn","Your OSRS character name",12);
    }
    static UUID request(Connection c,String discord,String name)throws SQLException {
        name=characterName(name);String normalized=Policy.normalize(name);
        // Serialize same-user submissions before checking link/request limits.
        try(PreparedStatement s=RankingStore.query(c,"SELECT pg_advisory_xact_lock(hashtextextended(?,91821))",discord)){s.executeQuery().close();}
        try(PreparedStatement s=RankingStore.query(c,"SELECT 1 FROM discord_member_links WHERE discord_user_id=?",discord);ResultSet r=s.executeQuery()) {
            if(r.next())throw new Policy.Rejected(409,"Your Discord account is already linked. Contact the Owner for account changes.");
        }
        try(PreparedStatement s=RankingStore.query(c,"SELECT id,normalized_name FROM discord_join_requests WHERE discord_user_id=? AND status='PENDING'",discord);ResultSet r=s.executeQuery()) {
            if(r.next()) {if(!r.getString(2).equals(normalized))throw new Policy.Rejected(409,"You already have a pending request. Ask staff to review it first.");return r.getObject(1,UUID.class);}
        }
        try(PreparedStatement s=RankingStore.query(c,"SELECT count(*) FROM discord_join_requests WHERE discord_user_id=? AND created_at>now()-interval '1 day'",discord);ResultSet r=s.executeQuery()) {
            r.next();if(r.getInt(1)>=5)throw new Policy.Rejected(429,"Request limit reached. Try again tomorrow.");
        }
        UUID id=UUID.randomUUID();
        try(PreparedStatement s=RankingStore.query(c,"INSERT INTO discord_join_requests(id,discord_user_id,character_name,normalized_name) VALUES (?,?,?,?) ON CONFLICT DO NOTHING",id,discord,name,normalized)) {
            if(s.executeUpdate()!=1)throw new Policy.Rejected(409,"That character has a pending request. Contact the Owner.");
        }
        JsonObject notification=new JsonObject();notification.addProperty("content","RuneLite link request: **"+name+"** — Discord ID `"+discord+"`. Staff: independently verify character ownership and current clan membership before approving.");
        notification.add("allowed_mentions",object("{\"parse\":[]}"));JsonArray buttons=new JsonArray();buttons.add(decisions(id));notification.add("components",buttons);
        RankingStore.execute(c,"INSERT INTO discord_join_outbox(id,payload) VALUES (?,?::jsonb)",id,notification.toString());return id;
    }
    static void review(Connection c,String discord,UUID request,boolean approve,String reason)throws SQLException {
        review(c,discord,request,approve,reason,false);
    }
    private static void review(Connection c,String discord,UUID request,boolean approve,String reason,boolean staff)throws SQLException {
        UUID actor=reviewer(c,discord,staff);
        if(reason==null||reason.trim().length()<10||reason.length()>1000)throw new Policy.Rejected(400,"Give a verification/rejection reason of 10–1000 characters.");
        try(PreparedStatement s=RankingStore.query(c,"SELECT discord_user_id,character_name,normalized_name,status FROM discord_join_requests WHERE id=? FOR UPDATE",request);ResultSet r=s.executeQuery()) {
            if(!r.next())throw new Policy.Rejected(404,"Request unavailable");
            if(!r.getString(4).equals("PENDING"))throw new Policy.Rejected(409,"This request was already reviewed.");
            String applicant=r.getString(1),name=r.getString(2),normalized=r.getString(3);UUID member=null;
            if(approve) {
                // Unique constraints also protect against a concurrent operator link.
                try(PreparedStatement existing=RankingStore.query(c,"SELECT 1 FROM discord_member_links l JOIN members m ON m.id=l.member_id WHERE l.discord_user_id=? OR m.normalized_name=?",applicant,normalized);ResultSet linked=existing.executeQuery()) {
                    if(linked.next())throw new Policy.Rejected(409,"Discord or character is already linked. No existing link was replaced.");
                }
                try(PreparedStatement existing=RankingStore.query(c,"SELECT id,active FROM members WHERE normalized_name=? FOR UPDATE",normalized);ResultSet found=existing.executeQuery()) {
                    if(found.next()) {if(!found.getBoolean(2))throw new Policy.Rejected(409,"Inactive characters require operator review before relinking.");member=found.getObject(1,UUID.class);}
                }
                if(member==null){member=UUID.randomUUID();RankingStore.execute(c,"INSERT INTO members(id,name,normalized_name) VALUES (?,?,?)",member,name,normalized);}
                RankingStore.execute(c,"INSERT INTO discord_member_links(discord_user_id,member_id) VALUES (?,?)",applicant,member);
            }
            RankingStore.execute(c,"UPDATE discord_join_requests SET status=?,reviewed_at=now(),reviewer=?,reviewer_discord_id=?,reason=?,member_id=? WHERE id=?",approve?"APPROVED":"REJECTED",actor,discord,reason.trim(),member,request);
            JsonObject details=new JsonObject();details.addProperty("request",request.toString());details.addProperty("discordUserId",applicant);details.addProperty("character",name);details.addProperty("reason",reason.trim());
            details.addProperty("reviewerDiscordId",discord);
            if(member!=null)details.addProperty("member",member.toString());
            RankingStore.execute(c,"INSERT INTO audit(actor,action,target,details) VALUES (?,?,?,?::jsonb)",actor,approve?"DISCORD_LINK_APPROVED":"DISCORD_LINK_REJECTED",member==null?request:member,details.toString());
            DiscordJoinArchive.enqueue(c,request);
        }
    }
    static JsonObject pending(Connection c,String discord)throws SQLException {
        return pending(c,discord,false);
    }
    private static JsonObject pending(Connection c,String discord,boolean staff)throws SQLException {
        reviewer(c,discord,staff);JsonObject reply=message("Pending RuneLite links (up to five oldest). Verify character ownership and clan membership before approval. Use /pending again for the next requests.");JsonArray rows=new JsonArray();StringBuilder content=new StringBuilder(reply.getAsJsonObject("data").get("content").getAsString());
        try(PreparedStatement s=RankingStore.query(c,"SELECT id,character_name,discord_user_id FROM discord_join_requests WHERE status='PENDING' ORDER BY created_at,id LIMIT 5");ResultSet r=s.executeQuery()) {
            while(r.next()) {UUID id=r.getObject(1,UUID.class);content.append("\n**").append(r.getString(2)).append("** — Discord ID `").append(r.getString(3)).append("`");
                JsonObject row=decisions(id);row.getAsJsonArray("components").get(0).getAsJsonObject().addProperty("label","Approve "+r.getString(2));row.getAsJsonArray("components").get(1).getAsJsonObject().addProperty("label","Reject "+r.getString(2));rows.add(row);}
        }
        if(rows.size()==0)content.append("\nNo pending requests.");reply.getAsJsonObject("data").addProperty("content",content.toString());reply.getAsJsonObject("data").add("components",rows);return reply;
    }
    static JsonObject dispatch(Connection c,JsonObject interaction,String discord)throws SQLException {
        return dispatch(c,interaction,discord,null);
    }
    static JsonObject dispatch(Connection c,JsonObject interaction,String discord,String staffRole)throws SQLException {
        boolean staff=staff(interaction,staffRole);
        int type=interaction.get("type").getAsInt();JsonObject data=interaction.getAsJsonObject("data");
        if(type==2) {
            String command=Policy.text(data,"name",32);if(command.equals("pending"))return pending(c,discord,staff);
            if(command.equals("link"))return linkForm(c,discord);
            if(command.equals("edit-link")||command.equals("revoke-link")) {
                owner(c,discord);
                return DiscordLinkManagement.form(c,discord,DiscordLinkManagement.target(data),command.equals("edit-link"));
            }
        } else {
            String custom=Policy.text(data,"custom_id",100);
            if(type==5&&custom.startsWith("linked:"))return DiscordLinkManagement.submit(c,discord,data);
            if(type==3&&custom.equals("join:start"))return linkForm(c,discord);
            if(type==5&&custom.equals("join:request")) {
                UUID request=request(c,discord,field(data,"rsn",12));return message("Request submitted: "+request+". Staff must verify and approve your character. After approval, click Sign in with Discord in RuneLite. No access is granted yet.");
            }
            if(type==3&&(custom.startsWith("join:approve:")||custom.startsWith("join:reject:"))) {
                reviewer(c,discord,staff);boolean approve=custom.startsWith("join:approve:");UUID id=Policy.uuid(custom.substring(custom.lastIndexOf(':')+1));
                DiscordJoinArchive.remember(c,interaction,id);
                if(!approve) {
                    JsonObject revoke=DiscordLinkManagement.rejectAccepted(c,discord,id);
                    if(revoke!=null)return revoke;
                }
                return modal((approve?"join:accept:":"join:deny:")+id,approve?"Confirm verified character":"Reject linking request","reason",approve?"How did you verify ownership and membership?":"Reason for rejection",1000);
            }
            if(type==5&&(custom.startsWith("join:accept:")||custom.startsWith("join:deny:"))) {
                boolean approve=custom.startsWith("join:accept:");review(c,discord,Policy.uuid(custom.substring(custom.lastIndexOf(':')+1)),approve,field(data,"reason",1000),staff);
                return message(approve?"Approved and linked. Ask the member to click Sign in with Discord in RuneLite. No staff permissions were granted.":"Request rejected. No access was granted.");
            }
        }
        throw new Policy.Rejected(400,"Unsupported Discord action");
    }
}

package com.traphouse.server;

import com.google.gson.*;
import java.sql.*;
import java.util.UUID;

/** Owner-only changes to an established link; never moves a link to another member. */
final class DiscordLinkManagement {
    private static final class Link {
        final UUID member;
        final Timestamp linkedAt;
        final String discord,name,version;
        Link(UUID member,String discord,String name,Timestamp linkedAt) {
            this.member=member;this.discord=discord;this.name=name;this.linkedAt=linkedAt;
            version=Policy.hash(member+":"+discord+":"+name+":"+linkedAt.toInstant()).substring(0,16);
        }
        String custom(String action) {return "linked:"+action+":"+discord+":"+member+":"+version;}
    }

    private static Link linked(Connection c,String discord)throws SQLException {
        try(PreparedStatement s=RankingStore.query(c,"SELECT m.id,m.name,l.linked_at FROM discord_member_links l JOIN members m ON m.id=l.member_id WHERE l.discord_user_id=? FOR UPDATE OF m,l",discord);ResultSet r=s.executeQuery()) {
            if(!r.next())throw new Policy.Rejected(404,"This Discord account has no accepted RuneLite link.");
            return new Link(r.getObject(1,UUID.class),discord,r.getString(2),r.getTimestamp(3));
        }
    }

    private static void protectOwner(Connection c,Link link)throws SQLException {
        try(PreparedStatement s=RankingStore.query(c,"SELECT 1 FROM member_permissions WHERE member_id=? AND permission='OWNER'",link.member);ResultSet r=s.executeQuery()) {
            if(r.next())throw new Policy.Rejected(403,"Owner identity changes require the server operator; the Owner link cannot be changed here.");
        }
    }

    static JsonObject form(Connection c,String owner,String target,boolean edit)throws SQLException {
        DiscordJoining.owner(c,owner);
        Link link=linked(c,DiscordLogin.snowflake(target));protectOwner(c,link);
        return form(link,edit);
    }

    private static JsonObject form(Link link,boolean edit) {
        JsonObject response=DiscordJoining.modal(link.custom(edit?"edit":"revoke"),edit?"Correct "+link.name:"Revoke "+link.name,"reason",edit?"How did you verify the correct character?":"Reason for revoking this accepted link",1000);
        if(edit) {
            JsonObject name=DiscordJoining.modal("unused","unused","rsn","Correct OSRS name (same person)",12);
            JsonArray rows=new JsonArray();rows.add(name.getAsJsonObject("data").getAsJsonArray("components").get(0));
            rows.add(response.getAsJsonObject("data").getAsJsonArray("components").get(0));
            response.getAsJsonObject("data").add("components",rows);
        }
        return response;
    }

    static JsonObject rejectAccepted(Connection c,String owner,UUID request)throws SQLException {
        String target;UUID member;Timestamp reviewed;
        try(PreparedStatement s=RankingStore.query(c,"SELECT discord_user_id,member_id,status,reviewed_at FROM discord_join_requests WHERE id=?",request);ResultSet r=s.executeQuery()) {
            if(!r.next()||!"APPROVED".equals(r.getString(3)))return null;
            target=r.getString(1);member=r.getObject(2,UUID.class);reviewed=r.getTimestamp(4);
        }
        DiscordJoining.owner(c,owner);
        Link link=linked(c,target);
        if(!link.member.equals(member)||!link.linkedAt.equals(reviewed))throw new Policy.Rejected(409,"This approval no longer matches the current link. Use /revoke-link instead.");
        protectOwner(c,link);return form(link,false);
    }

    static JsonObject submit(Connection c,String owner,JsonObject data)throws SQLException {
        RankingStore.Actor actor=DiscordJoining.owner(c,owner);
        String[] parts=Policy.text(data,"custom_id",100).split(":");
        if(parts.length!=5||!parts[0].equals("linked")||!(parts[1].equals("edit")||parts[1].equals("revoke")))throw new Policy.Rejected(400,"Invalid link action");
        Link link=linked(c,DiscordLogin.snowflake(parts[2]));
        if(!link.member.equals(Policy.uuid(parts[3]))||!link.version.equals(parts[4]))throw new Policy.Rejected(409,"This link changed after the form opened. Run the command again.");
        protectOwner(c,link);
        String reason=DiscordJoining.field(data,"reason",1000).trim();
        if(reason.length()<10)throw new Policy.Rejected(400,"Give a reason of 10–1000 characters.");
        boolean edit=parts[1].equals("edit");String newName=null;
        if(edit) {
            newName=DiscordJoining.characterName(DiscordJoining.field(data,"rsn",12));
            try(PreparedStatement s=RankingStore.query(c,"SELECT 1 FROM members WHERE normalized_name=? AND id<>?",Policy.normalize(newName),link.member);ResultSet r=s.executeQuery()) {
                if(r.next())throw new Policy.Rejected(409,"That name already has a member record. No records were merged; contact the server operator.");
            }
            RankingStore.execute(c,"UPDATE members SET name=?,normalized_name=? WHERE id=?",newName,Policy.normalize(newName),link.member);
        } else RankingStore.execute(c,"DELETE FROM discord_member_links WHERE discord_user_id=? AND member_id=?",link.discord,link.member);
        RankingStore.execute(c,"UPDATE credentials SET revoked=true WHERE member_id=? AND NOT revoked",link.member);
        RankingStore.execute(c,"DELETE FROM discord_login_sessions WHERE member_id=?",link.member);
        JsonObject details=new JsonObject();details.addProperty("discordUserId",link.discord);details.addProperty("oldName",link.name);
        if(edit)details.addProperty("newName",newName);details.addProperty("reason",reason);
        RankSecurity.audit(c,actor,edit?"DISCORD_LINK_NAME_CORRECTED":"DISCORD_LINK_REVOKED",link.member,details);
        return DiscordJoining.message(edit?"Name corrected to "+newName+". Ask the member to sign in with Discord again. Points and history were preserved.":"Accepted link revoked for "+link.name+". Existing credentials and sign-in sessions were revoked. Points and history were preserved. A new /link request requires Owner approval.");
    }

    static String target(JsonObject data) {
        String target=null;
        if(data.has("options"))for(JsonElement element:data.getAsJsonArray("options")) {
            JsonObject option=element.getAsJsonObject();
            if("member".equals(Policy.text(option,"name",32))) {
                if(target!=null||option.get("type").getAsInt()!=6)throw new Policy.Rejected(400,"Choose one Discord member.");
                target=DiscordLogin.snowflake(Policy.text(option,"value",20));
            }
        }
        if(target==null)throw new Policy.Rejected(400,"Choose a Discord member.");return target;
    }
}

package com.traphouse.server;

import com.google.gson.*;
import com.sun.net.httpserver.HttpExchange;
import java.io.*;
import java.net.*;
import java.net.http.*;
import java.nio.charset.StandardCharsets;
import java.security.SecureRandom;
import java.sql.*;
import java.time.Duration;
import java.util.*;

/** Discord identifies a preverified roster entry; it never supplies permissions or an OSRS identity. */
final class DiscordLogin {
    private static final Gson JSON = new Gson();
    private static final SecureRandom RANDOM = new SecureRandom();
    private static long minute;
    private static int starts;
    private static final HttpClient HTTP = HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(10))
        .followRedirects(HttpClient.Redirect.NEVER).build();
    interface IdentityProvider { String identify(String code) throws Exception; }
    private final DiscordWorker.Connections connections;
    private final Map<String,String> env;
    private final IdentityProvider provider;

    DiscordLogin(DiscordWorker.Connections connections) { this(connections, System.getenv(), null); }
    DiscordLogin(DiscordWorker.Connections connections, Map<String,String> env, IdentityProvider provider) {
        this.connections=connections; this.env=env; this.provider=provider == null ? this::discordIdentity : provider;
    }
    static boolean matches(String path) { return path.startsWith("/auth/discord/"); }
    static String secret() { byte[] b=new byte[32]; RANDOM.nextBytes(b); return Base64.getUrlEncoder().withoutPadding().encodeToString(b); }
    static String capability(JsonObject body) {
        String value=Policy.text(body,"secret",43);
        if(!value.matches("[A-Za-z0-9_-]{43}"))throw new Policy.Rejected(400,"Invalid login secret");
        return value;
    }
    static String snowflake(String value) {
        if(value==null||!value.matches("[0-9]{17,20}"))throw new IllegalArgumentException("Invalid Discord user ID");
        return value;
    }
    private String required(String key) {
        String value=env.get(key);
        if(value==null||value.isBlank())throw new Policy.Rejected(503,"Discord sign-in is not configured yet");
        return value;
    }
    private String origin() {
        String value=required("TRAP_PUBLIC_URL");
        URI uri=URI.create(value);
        if(!"https".equals(uri.getScheme())||uri.getHost()==null||uri.getUserInfo()!=null||uri.getQuery()!=null||uri.getFragment()!=null
            ||!(uri.getPath().isEmpty()||uri.getPath().equals("/")))throw new Policy.Rejected(503,"Invalid public API address");
        return value.replaceAll("/+$","");
    }
    private static synchronized void limitStarts() {
        long now=System.currentTimeMillis()/60000;
        if(now!=minute){minute=now;starts=0;}
        if(++starts>30)throw new Policy.Rejected(429,"Too many sign-in attempts; try again in a minute");
    }
    static Map<String,String> parameters(String query) {
        Map<String,String> result=new HashMap<>();
        if(query==null||query.length()>4096)throw new Policy.Rejected(400,"Invalid sign-in link");
        for(String part:query.split("&")) {
            String[] pair=part.split("=",2);
            String key=URLDecoder.decode(pair[0],StandardCharsets.UTF_8);
            if(pair.length!=2||result.put(key,URLDecoder.decode(pair[1],StandardCharsets.UTF_8))!=null)
                throw new Policy.Rejected(400,"Invalid sign-in link");
        }
        return result;
    }
    void handle(HttpExchange exchange) throws IOException {
        int status=200; String type="application/json; charset=utf-8"; String output;
        try {
            String path=exchange.getRequestURI().getPath(), method=exchange.getRequestMethod();
            if(method.equals("POST")&&path.equals("/auth/discord/device")) {
                limitStarts(); required("TRAP_DISCORD_CLIENT_ID");required("TRAP_DISCORD_CLIENT_SECRET");required("TRAP_DISCORD_GUILD_ID");
                JsonObject body=RankingServer.readBody(exchange);String hash=Policy.hash(capability(body));
                UUID id=UUID.randomUUID();String browser=secret();
                try(Connection c=connections.open()) {
                    RankingStore.execute(c,"DELETE FROM discord_login_sessions WHERE expires_at<now()");
                    RankingStore.execute(c,"INSERT INTO discord_login_sessions(id,device_hash,browser_hash) VALUES (?,?,?)",id,hash,Policy.hash(browser));
                }
                JsonObject data=new JsonObject();data.addProperty("session",id.toString());data.addProperty("expiresIn",600);
                data.addProperty("url",origin()+"/auth/discord/start?session="+id+"&browser="+browser);output=JSON.toJson(data);
            } else if(method.equals("GET")&&path.equals("/auth/discord/start")) {
                Map<String,String> params=parameters(exchange.getRequestURI().getRawQuery());
                UUID id=Policy.uuid(params.getOrDefault("session",""));String browser=params.getOrDefault("browser","");String state=secret();
                try(Connection c=connections.open();PreparedStatement s=RankingStore.query(c,
                    "UPDATE discord_login_sessions SET state_hash=? WHERE id=? AND browser_hash=? AND expires_at>now() AND state_hash IS NULL RETURNING id",
                    Policy.hash(state),id,Policy.hash(browser));ResultSet r=s.executeQuery()) {
                    if(!r.next())throw new Policy.Rejected(400,"Sign-in link expired or already opened; start again in RuneLite");
                }
                String location="https://discord.com/oauth2/authorize?response_type=code&client_id="+encode(required("TRAP_DISCORD_CLIENT_ID"))
                    +"&redirect_uri="+encode(origin()+"/auth/discord/callback")+"&scope=identify%20guilds.members.read&state="+state+"&prompt=consent";
                exchange.getResponseHeaders().set("Location",location);status=302;output="{}";
            } else if(method.equals("GET")&&path.equals("/auth/discord/callback")) {
                Map<String,String> params=parameters(exchange.getRequestURI().getRawQuery());
                String state=params.getOrDefault("state","");
                if(!state.matches("[A-Za-z0-9_-]{43}")||!params.containsKey("code"))throw new Policy.Rejected(400,"Sign-in cancelled or invalid; start again in RuneLite");
                try(Connection c=connections.open()) {
                    c.setAutoCommit(false);
                    try {
                        UUID session;
                        try(PreparedStatement s=RankingStore.query(c,"SELECT id FROM discord_login_sessions WHERE state_hash=? AND expires_at>now() AND NOT callback_used FOR UPDATE",Policy.hash(state));ResultSet r=s.executeQuery()) {
                            if(!r.next())throw new Policy.Rejected(400,"Sign-in expired or already completed");session=r.getObject(1,UUID.class);
                        }
                        // Consume before contacting Discord: failed or replayed callbacks require a new login.
                        RankingStore.execute(c,"UPDATE discord_login_sessions SET callback_used=true WHERE id=?",session);c.commit();
                        String discord=snowflake(provider.identify(params.get("code")));
                        UUID member;
                        try(PreparedStatement s=RankingStore.query(c,"SELECT m.id FROM discord_member_links l JOIN members m ON m.id=l.member_id WHERE l.discord_user_id=? AND m.active FOR SHARE OF m,l",discord);ResultSet r=s.executeQuery()) {
                            if(!r.next()) {
                                c.rollback();
                                reply(exchange,403,"text/html; charset=utf-8",page("Account linking required","In the clan Discord, click Link RuneLite or use /link to request a character link. After the Owner verifies and approves it, start sign-in again in RuneLite. If the button is not configured, ask leadership to link Discord user ID "+discord+". No access has been granted."));return;
                            }
                            member=r.getObject(1,UUID.class);
                        }
                        RankingStore.execute(c,"UPDATE discord_login_sessions SET member_id=? WHERE id=?",member,session);c.commit();
                    } catch(Exception failure){c.rollback();throw failure;}
                }
                type="text/html; charset=utf-8";output=page("Discord sign-in complete","Return to RuneLite. It will finish connecting automatically.");
            } else if(method.equals("POST")&&path.equals("/auth/discord/poll")) {
                JsonObject body=RankingServer.readBody(exchange);UUID id=Policy.uuid(Policy.text(body,"session",36));String hash=Policy.hash(capability(body));
                JsonObject data=new JsonObject();data.addProperty("status","pending");
                try(Connection c=connections.open()) {
                    c.setAutoCommit(false);
                    try {
                        UUID member;
                        try(PreparedStatement s=RankingStore.query(c,"SELECT member_id,last_poll FROM discord_login_sessions WHERE id=? AND device_hash=? AND expires_at>now() FOR UPDATE",id,hash);ResultSet r=s.executeQuery()) {
                            if(!r.next())throw new Policy.Rejected(410,"Sign-in expired; start again");
                            Timestamp previous=r.getTimestamp(2);
                            if(previous!=null&&previous.toInstant().plusSeconds(3).isAfter(java.time.Instant.now()))throw new Policy.Rejected(429,"Please wait before checking sign-in again");
                            member=r.getObject(1,UUID.class);
                        }
                        RankingStore.execute(c,"UPDATE discord_login_sessions SET last_poll=now() WHERE id=?",id);
                        if(member!=null) {
                            RankingStore.lockMember(c,member);
                            String token=secret();
                            RankingStore.execute(c,"INSERT INTO credentials(token_hash,member_id,expires_at) VALUES (?,?,now()+interval '90 days')",Policy.hash(token),member);
                            RankingStore.execute(c,"INSERT INTO audit(actor,action,target) VALUES (?,'DISCORD_CREDENTIAL_ISSUED',?)",member,member);
                            RankingStore.execute(c,"DELETE FROM discord_login_sessions WHERE id=?",id);
                            data.addProperty("status","complete");data.addProperty("token",token);
                        }
                        c.commit();
                    } catch(Exception failure){c.rollback();throw failure;}
                }
                output=JSON.toJson(data);
            } else throw new Policy.Rejected(404,"Unknown sign-in route");
        } catch(Policy.Rejected rejected) { status=rejected.status;JsonObject error=new JsonObject();error.addProperty("error",rejected.getMessage());output=JSON.toJson(error);
        } catch(IllegalArgumentException|JsonParseException invalid) {status=400;output="{\"error\":\"Invalid sign-in request\"}";
        } catch(Exception failure) {status=503;output="{\"error\":\"Discord sign-in unavailable; start again shortly\"}";}
        reply(exchange,status,type,output);
    }
    private static String page(String title,String message) {
        return "<!doctype html><html><meta charset='utf-8'><meta name='viewport' content='width=device-width'><title>TRAP HOUSE sign-in</title><body style='background:#11151c;color:#eee;font:18px system-ui;max-width:640px;margin:80px auto;padding:24px'><h1>"+title+"</h1><p>"+message+"</p></body></html>";
    }
    private static void reply(HttpExchange exchange,int status,String type,String body)throws IOException {
        byte[] bytes=body.getBytes(StandardCharsets.UTF_8);
        exchange.getResponseHeaders().set("Content-Type",type);exchange.getResponseHeaders().set("Cache-Control","no-store");
        exchange.getResponseHeaders().set("Referrer-Policy","no-referrer");exchange.getResponseHeaders().set("X-Content-Type-Options","nosniff");
        exchange.getResponseHeaders().set("Content-Security-Policy","default-src 'none'; style-src 'unsafe-inline'; frame-ancestors 'none'; base-uri 'none'");
        exchange.sendResponseHeaders(status,bytes.length);try(OutputStream out=exchange.getResponseBody()){out.write(bytes);}finally{exchange.close();}
    }
    private static String encode(String value){return URLEncoder.encode(value,StandardCharsets.UTF_8);}
    static String verificationError(String step,int status) {
        if(step.equals("token"))return "Discord sign-in configuration was rejected (HTTP "+status+"). Check that the Render Client ID and Client Secret belong to the same Discord application and that its redirect URL matches exactly. Then start a new sign-in from RuneLite.";
        if(step.equals("identity"))return "Discord could not verify your account (HTTP "+status+"). Start a new sign-in from RuneLite and authorize it again.";
        return "Discord server membership could not be verified (HTTP "+status+"). Check that TRAP_DISCORD_GUILD_ID is your clan server ID and that the Discord account you authorized has joined that server. Then start a new sign-in from RuneLite.";
    }
    private JsonObject fetch(HttpRequest request,String step)throws Exception {
        HttpResponse<InputStream> response=HTTP.send(request,HttpResponse.BodyHandlers.ofInputStream());
        try(InputStream input=response.body()) {
            byte[] bytes=input.readNBytes(65537);
            if(response.statusCode()!=200)throw new Policy.Rejected(403,verificationError(step,response.statusCode()));
            if(bytes.length>65536)throw new Policy.Rejected(503,"Discord returned an invalid response; start a new sign-in shortly");
            return JsonParser.parseString(new String(bytes,StandardCharsets.UTF_8)).getAsJsonObject();
        }
    }
    private String discordIdentity(String code)throws Exception {
        String form="grant_type=authorization_code&code="+encode(code)+"&client_id="+encode(required("TRAP_DISCORD_CLIENT_ID"))
            +"&client_secret="+encode(required("TRAP_DISCORD_CLIENT_SECRET"))+"&redirect_uri="+encode(origin()+"/auth/discord/callback");
        JsonObject tokens=fetch(HttpRequest.newBuilder(URI.create("https://discord.com/api/v10/oauth2/token")).timeout(Duration.ofSeconds(15))
            .header("Content-Type","application/x-www-form-urlencoded").POST(HttpRequest.BodyPublishers.ofString(form)).build(),"token");
        String access=Policy.text(tokens,"access_token",4096);
        JsonObject user=fetch(HttpRequest.newBuilder(URI.create("https://discord.com/api/v10/users/@me")).timeout(Duration.ofSeconds(15)).header("Authorization","Bearer "+access).build(),"identity");
        fetch(HttpRequest.newBuilder(URI.create("https://discord.com/api/v10/users/@me/guilds/"+snowflake(required("TRAP_DISCORD_GUILD_ID"))+"/member"))
            .timeout(Duration.ofSeconds(15)).header("Authorization","Bearer "+access).build(),"membership");
        return snowflake(Policy.text(user,"id",20));
    }
}

package com.traphouse.server;

import com.google.gson.*;
import java.net.URI;
import java.net.http.*;
import java.sql.*;
import java.time.Duration;
import java.util.UUID;

/** Transactional outbox, at-least-once delivery. Mentions are always disabled. */
final class DiscordWorker implements Runnable {
    interface Connections { Connection open() throws SQLException; }
    private final Connections connections;
    private final URI webhook;
    private final HttpClient http = HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(5))
        .followRedirects(HttpClient.Redirect.NEVER).build();

    DiscordWorker(Connections connections, String url) {
        this.connections = connections;
        webhook = validate(url);
    }

    static URI validate(String url) {
        URI uri = URI.create(url);
        if (!"https".equals(uri.getScheme()) || !"discord.com".equals(uri.getHost())
            || uri.getPort() != -1 || uri.getUserInfo() != null || uri.getQuery() != null || uri.getFragment() != null
            || !uri.getPath().matches("/api/webhooks/[0-9]+/[A-Za-z0-9_-]+")) {
            throw new IllegalArgumentException("Use an HTTPS discord.com webhook URL");
        }
        return uri;
    }

    static String payload(String content) {
        JsonObject body = new JsonObject();
        body.addProperty("content", content);
        JsonObject mentions = new JsonObject(); mentions.add("parse", new JsonArray());
        body.add("allowed_mentions", mentions);
        return new Gson().toJson(body);
    }

    @Override public void run() {
        try (Connection c = connections.open()) {
            c.setAutoCommit(false);
            try (PreparedStatement s = RankingStore.query(c, "SELECT id,content,attempts FROM discord_outbox WHERE delivered_at IS NULL AND next_attempt<=now() ORDER BY created_at LIMIT 1 FOR UPDATE SKIP LOCKED"); ResultSet r = s.executeQuery()) {
                if (!r.next()) { c.commit(); return; }
                UUID id = r.getObject(1, UUID.class);
                int attempts = r.getInt(3);
                boolean delivered = false;
                try {
                    HttpRequest request = HttpRequest.newBuilder(webhook).timeout(Duration.ofSeconds(10))
                        .header("Content-Type", "application/json")
                        .POST(HttpRequest.BodyPublishers.ofString(payload(r.getString(2)))).build();
                    int status = http.send(request, HttpResponse.BodyHandlers.discarding()).statusCode();
                    delivered = status >= 200 && status < 300;
                } catch (java.io.IOException failure) {
                    // Persist retry without logging secret webhook URLs or HTTP response bodies.
                } catch (InterruptedException stopped) {
                    Thread.currentThread().interrupt(); return;
                }
                if (delivered) RankingStore.execute(c, "UPDATE discord_outbox SET delivered_at=now(),attempts=attempts+1 WHERE id=?", id);
                else RankingStore.execute(c, "UPDATE discord_outbox SET attempts=attempts+1,next_attempt=now()+(? * interval '1 second') WHERE id=?", Math.min(3600, 60L << Math.min(attempts, 6)), id);
                c.commit();
            }
        } catch (SQLException unavailable) { System.err.println("Discord outbox unavailable; will retry."); }
    }
}

package com.traphouse.server;

import java.math.*;
import java.sql.*;
import java.time.*;
import java.time.temporal.TemporalAdjusters;
import java.util.UUID;

/** Positive rewards from server-fetched WOM deltas only. Never accepts client observations. */
final class EfficiencyRewards {
    static final BigDecimal EHP_RATE=BigDecimal.valueOf(10), EHB_RATE=BigDecimal.valueOf(10);
    static final int WEEKLY_CAP=250;
    static Instant week(Instant now) {
        return now.atZone(ZoneOffset.UTC).toLocalDate().with(TemporalAdjusters.previousOrSame(DayOfWeek.MONDAY)).atStartOfDay(ZoneOffset.UTC).toInstant();
    }
    static BigDecimal earned(BigDecimal oldEhp,BigDecimal oldEhb,BigDecimal ehp,BigDecimal ehb) {
        return ehp.subtract(oldEhp).max(BigDecimal.ZERO).multiply(EHP_RATE)
            .add(ehb.subtract(oldEhb).max(BigDecimal.ZERO).multiply(EHB_RATE));
    }
    static int payout(BigDecimal earned,int paid) {
        return earned.max(BigDecimal.ZERO).min(BigDecimal.valueOf(Math.max(0,WEEKLY_CAP-paid))).setScale(0,RoundingMode.DOWN).intValueExact();
    }
    static void observe(Connection c,RankingStore.Actor actor,BigDecimal ehp,BigDecimal ehb,Instant snapshot,Instant now)throws SQLException {
        RankingStore.lockMember(c,actor.id);
        // Old data may be displayed, but cannot establish an earning baseline or grant rewards.
        if(snapshot==null||snapshot.isBefore(now.minus(Duration.ofHours(24)))||snapshot.isAfter(now.plusSeconds(300)))return;
        ehp=ehp.setScale(8,RoundingMode.DOWN);ehb=ehb.setScale(8,RoundingMode.DOWN);
        Instant week=week(now);
        try(PreparedStatement s=RankingStore.query(c,"SELECT ehp_high,ehb_high,last_snapshot,week_start,weekly_points,carry FROM efficiency_reward_state WHERE member_id=? FOR UPDATE",actor.id);ResultSet r=s.executeQuery()) {
            if(!r.next()) {
                RankingStore.execute(c,"INSERT INTO efficiency_reward_state(member_id,ehp_high,ehb_high,last_snapshot,baseline_at,week_start) VALUES (?,?,?,?,?,?)",actor.id,ehp,ehb,Timestamp.from(snapshot),Timestamp.from(now),Timestamp.from(week));
                return;
            }
            if(!snapshot.isAfter(r.getTimestamp(3).toInstant()))return;
            BigDecimal oldEhp=r.getBigDecimal(1),oldEhb=r.getBigDecimal(2);
            boolean sameWeek=week.equals(r.getTimestamp(4).toInstant());
            int paid=sameWeek?r.getInt(5):0;
            BigDecimal amount=earned(oldEhp,oldEhb,ehp,ehb).add(sameWeek?r.getBigDecimal(6):BigDecimal.ZERO);
            int points=payout(amount,paid);
            BigDecimal carry=paid+points>=WEEKLY_CAP?BigDecimal.ZERO:amount.subtract(BigDecimal.valueOf(points));
            if(points>0) {
                UUID event=UUID.randomUUID();
                UUID request=UUID.nameUUIDFromBytes(("efficiency-v1:"+actor.id+":"+snapshot).getBytes(java.nio.charset.StandardCharsets.UTF_8));
                RankingStore.execute(c,"INSERT INTO events(id,member_id,client_id,type,event_key,observed_at,points) VALUES (?,?,?,'EFFICIENCY','WOM EHP/EHB gains',?,?)",event,actor.id,request,Timestamp.from(snapshot),points);
                RankingStore.award(c,actor,event,null,points,"Wise Old Man efficiency gains (weekly cap "+WEEKLY_CAP+")","Efficiency");
            }
            RankingStore.execute(c,"UPDATE efficiency_reward_state SET ehp_high=?,ehb_high=?,last_snapshot=?,week_start=?,weekly_points=?,carry=? WHERE member_id=?",
                oldEhp.max(ehp),oldEhb.max(ehb),Timestamp.from(snapshot),Timestamp.from(week),paid+points,carry,actor.id);
        }
    }
}

