package com.traphouse.server;

import com.google.gson.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.sql.*;
import java.util.*;

/** Additive catalog: existing rewards, progress, goal identities, and staff edits are retained. */
final class MilestoneCatalog {
    static int boostedReward(int points) {
        if(points<1||points>100000)throw new IllegalArgumentException("Invalid reward");
        return Math.min(100000,((points*3+5)/10)*5);
    }
    static int currentReward(int original) { return Math.min(100000,boostedReward(original)*2); }
    static void applyRewardBoost(Connection c)throws IOException,SQLException { applyRewardBoost(c,false); }
    static void applyCurrentRewards(Connection c)throws IOException,SQLException { applyRewardBoost(c,true); }
    private static void applyRewardBoost(Connection c,boolean current)throws IOException,SQLException {
        String migration=current?"milestone-rewards-v3":"milestone-rewards-v2";
        try(Statement s=c.createStatement()){s.execute("SELECT pg_advisory_xact_lock(72419051001)");}
        try(PreparedStatement s=RankingStore.query(c,"SELECT 1 FROM configuration_migrations WHERE name=?",migration);ResultSet r=s.executeQuery()) {
            if(r.next())return;
        }
        for(JsonElement entry:rewards()) {
            JsonObject reward=entry.getAsJsonObject();UUID goal=UUID.fromString(reward.get("id").getAsString());
            int base=reward.get("points").getAsInt();
            int original=current?boostedReward(base):base,increased=current?currentReward(base):boostedReward(base);
            String name,category;
            try(PreparedStatement s=RankingStore.query(c,"SELECT name,category,points,enabled FROM goals WHERE id=? FOR UPDATE",goal);ResultSet r=s.executeQuery()) {
                if(!r.next())throw new IllegalStateException("Reward goal missing from catalog");
                // Respect operator overrides and disabled goals.
                if(r.getInt(3)!=original||!r.getBoolean(4))continue;
                name=r.getString(1);category=r.getString(2);
            }
            RankingStore.execute(c,"UPDATE goals SET points=? WHERE id=?",increased,goal);
            try(PreparedStatement s=RankingStore.query(c,"SELECT m.id,m.name FROM goal_progress p JOIN members m ON m.id=p.member_id WHERE p.goal_id=? AND p.award_event IS NOT NULL AND m.active ORDER BY m.id",goal);ResultSet r=s.executeQuery()) {
                while(r.next()) {
                    RankingStore.Actor member=new RankingStore.Actor(r.getObject(1,UUID.class),r.getString(2),false);
                    RankingStore.lockMember(c,member.id);
                    long paid;
                    try(PreparedStatement total=RankingStore.query(c,"SELECT coalesce(sum(l.points),0) FROM ledger l JOIN events e ON e.id=l.event_id WHERE l.member_id=? AND e.type='GOAL' AND e.event_key=?",member.id,goal.toString());ResultSet amounts=total.executeQuery()){amounts.next();paid=amounts.getLong(1);}
                    int difference=(int)Math.max(0L,increased-paid);if(difference==0)continue;
                    UUID event=UUID.randomUUID();
                    UUID request=UUID.nameUUIDFromBytes((migration+":"+member.id+":"+goal).getBytes(StandardCharsets.UTF_8));
                    int inserted;
                    try(PreparedStatement insert=RankingStore.query(c,"INSERT INTO events(id,member_id,client_id,type,event_key,observed_at,points) VALUES (?,?,?,'GOAL',?,now(),?) ON CONFLICT(member_id,client_id) DO NOTHING",event,member.id,request,goal.toString(),difference)){inserted=insert.executeUpdate();}
                    if(inserted==1) {
                        RankingStore.award(c,member,event,null,difference,name+" - milestone reward increase",category);
                        JsonObject details=new JsonObject();details.addProperty("source",migration+" deployment migration");
                        details.addProperty("goal",goal.toString());details.addProperty("points",difference);
                        details.addProperty("previouslyAwarded",paid);details.addProperty("newReward",increased);
                        details.addProperty("reason","Owner-authorized milestone reward increase");
                        RankingServer.operatorAudit(c,member.id,"MILESTONE_REWARD_TOPUP",details);
                    }
                }
            }
        }
        RankingStore.execute(c,"INSERT INTO configuration_migrations(name) VALUES (?)",migration);
    }
    static JsonArray rewards() throws IOException {
        try(InputStream input=MilestoneCatalog.class.getResourceAsStream("/milestone-rewards-v1.json")) {
            if(input==null)throw new IOException("Milestone rewards missing");
            return JsonParser.parseString(new String(input.readAllBytes(),StandardCharsets.UTF_8)).getAsJsonArray();
        }
    }
    static void applyRewards(Connection c)throws IOException,SQLException {
        // Caller owns the transaction. All reward edits and the marker commit together.
        try(Statement s=c.createStatement()){s.execute("SELECT pg_advisory_xact_lock(72419051001)");}
        try(PreparedStatement s=RankingStore.query(c,"SELECT 1 FROM configuration_migrations WHERE name='milestone-rewards-v1'");ResultSet r=s.executeQuery()) {
            if(r.next())return;
        }
        for(JsonElement entry:rewards()) {
            JsonObject reward=entry.getAsJsonObject();UUID id=UUID.fromString(reward.get("id").getAsString());
            int points=reward.get("points").getAsInt();
            if(points<1||points>100000)throw new IllegalStateException("Invalid milestone reward");
            try(PreparedStatement s=RankingStore.query(c,"SELECT points FROM goals WHERE id=? FOR UPDATE",id);ResultSet r=s.executeQuery()) {
                if(!r.next())throw new IllegalStateException("Reward goal missing from catalog");
                // Preserve previously configured positive rewards and disabled goals.
                if(r.getInt(1)==0)RankingStore.execute(c,"UPDATE goals SET points=? WHERE id=?",points,id);
            }
        }
        RankingStore.execute(c,"INSERT INTO configuration_migrations(name) VALUES ('milestone-rewards-v1')");
    }
    static JsonArray read() throws IOException {
        try(InputStream input=MilestoneCatalog.class.getResourceAsStream("/milestones.json")) {
            if(input==null)throw new IOException("Milestone catalog missing");
            return JsonParser.parseString(new String(input.readAllBytes(),StandardCharsets.UTF_8)).getAsJsonArray();
        }
    }
    static void seed(Connection c)throws IOException,SQLException {
        int sort=100;
        for(JsonElement entry:read()) {
            JsonObject goal=entry.getAsJsonObject();
            String source=goal.get("source").getAsString();
            String description=source.equals("QUEST")?"Completed quest read from your current game state.":"Your current unboosted skill or total level. Each configured milestone can award only once.";
            RankingStore.execute(c,"INSERT INTO goals(id,name,description,category,section,source,source_key,target,points,enabled,sort_order) VALUES (?,?,?,'Milestones',?,?,?,?,0,true,?) ON CONFLICT(id) DO NOTHING",
                UUID.fromString(goal.get("id").getAsString()),goal.get("name").getAsString(),description,goal.get("section").getAsString(),source,goal.get("sourceKey").getAsString(),goal.get("target").getAsLong(),sort++);
        }
    }
}

package com.traphouse.server;

import com.google.gson.*;
import java.sql.*;

/** A member's confirmed positive awards, paged in insertion order. No historical backfill. */
final class PointNotifications {
    static JsonObject read(Connection c,RankingStore.Actor actor,String query)throws SQLException {
        Long after=null;
        if(query!=null) {
            if(!query.matches("after=[0-9]{1,19}"))throw new Policy.Rejected(400,"Expected an award cursor");
            try {after=Long.parseLong(query.substring(6));}
            catch(NumberFormatException invalid){throw new Policy.Rejected(400,"Invalid award cursor");}
        }
        // Award writers lock this member before allocating notification IDs. Waiting here
        // ensures an in-flight award cannot later commit behind the returned cursor.
        RankingStore.lockMember(c,actor.id);
        long cursor=after==null?0:after;
        JsonArray awards=new JsonArray();
        if(after==null) {
            try(PreparedStatement s=RankingStore.query(c,"SELECT coalesce(max(id),0) FROM point_notifications WHERE member_id=?",actor.id);ResultSet r=s.executeQuery()) {
                r.next();cursor=r.getLong(1);
            }
        } else {
            try(PreparedStatement s=RankingStore.query(c,"SELECT n.id,n.points,n.title,l.category FROM point_notifications n JOIN ledger l ON l.id=n.ledger_id WHERE n.member_id=? AND n.id>? ORDER BY n.id LIMIT 100",actor.id,after);ResultSet r=s.executeQuery()) {
                while(r.next()) {
                    JsonObject award=new JsonObject();cursor=r.getLong(1);
                    award.addProperty("id",Long.toString(cursor));award.addProperty("points",r.getInt(2));award.addProperty("title",r.getString(3));award.addProperty("category",r.getString(4));awards.add(award);
                }
            }
        }
        JsonObject result=new JsonObject();result.addProperty("player",actor.name);
        result.addProperty("cursor",Long.toString(cursor));result.add("awards",awards);return result;
    }
}

package com.traphouse.server;

import com.google.gson.*;
import java.net.URLDecoder;
import java.nio.charset.StandardCharsets;
import java.sql.*;
import java.util.*;
import static com.traphouse.server.RankingStore.query;

/** Read-only, bounded member ledger browser. All user values are bound parameters. */
final class PointsLog {
    static final List<String> CATEGORIES=Arrays.asList("All","Drops","Clues","Pets","Milestones","Diaries","Challenges","Events","Combat","Collection","Efficiency","Misc");
    static Map<String,String> parameters(String raw) {
        if(raw==null||raw.length()>2000)throw new Policy.Rejected(400,"Invalid log query");
        Map<String,String> p=new HashMap<>();
        for(String part:raw.split("&")) {
            String[] pair=part.split("=",2);
            if(pair.length!=2)throw new Policy.Rejected(400,"Invalid log query");
            String key=URLDecoder.decode(pair[0],StandardCharsets.UTF_8),value=URLDecoder.decode(pair[1],StandardCharsets.UTF_8);
            if(!Arrays.asList("player","category","sort","search","group","page").contains(key)||p.put(key,value)!=null)throw new Policy.Rejected(400,"Invalid log parameter");
        }
        p.putIfAbsent("category","All");p.putIfAbsent("sort","newest");p.putIfAbsent("search","");p.putIfAbsent("group","false");p.putIfAbsent("page","1");
        if(!p.getOrDefault("player","").matches("[A-Za-z0-9 _-]{1,12}")||!CATEGORIES.contains(p.get("category"))||!Arrays.asList("newest","oldest","highest").contains(p.get("sort"))||p.get("search").length()>100||!Arrays.asList("true","false").contains(p.get("group"))||!p.get("page").matches("[1-9][0-9]{0,5}"))throw new Policy.Rejected(400,"Invalid log filter");
        return p;
    }
    static JsonObject read(Connection c,String raw)throws SQLException {
        Map<String,String> p=parameters(raw);UUID member;String name;
        try(PreparedStatement s=query(c,"SELECT id,name FROM members WHERE normalized_name=? AND active",Policy.normalize(p.get("player")));ResultSet r=s.executeQuery()) {
            if(!r.next())throw new Policy.Rejected(404,"Member unavailable");member=r.getObject(1,UUID.class);name=r.getString(2);
        }
        String base="WITH entries AS (SELECT l.category,l.points,l.created_at,coalesce(g.name,a.reason,nullif(rule.display_name,''),e.event_key,r.event_key,'Award') AS title,coalesce(e.type,'MANUAL') AS source_type,coalesce(e.event_key,r.event_key,'') AS source_key FROM point_entries l LEFT JOIN point_adjustments a ON a.id=l.id LEFT JOIN events e ON e.id=l.event_id LEFT JOIN manual_rewards r ON r.id=l.reward_id LEFT JOIN goals g ON e.type='GOAL' AND g.id::text=e.event_key LEFT JOIN rules rule ON rule.type=coalesce(e.type,'MANUAL') AND rule.event_key=coalesce(e.event_key,r.event_key) WHERE l.member_id=?), filtered AS (SELECT * FROM entries WHERE (?='All' OR category=?) AND strpos(lower(title),lower(?))>0), rows AS (";
        base+=p.get("group").equals("true")?"SELECT category,title,source_type,source_key,sum(points) AS points,max(created_at) AS created_at,count(*) AS occurrences FROM filtered GROUP BY category,title,source_type,source_key) ":"SELECT *,1 AS occurrences FROM filtered) ";
        Object[] args={member,p.get("category"),p.get("category"),p.get("search")};
        JsonObject result=new JsonObject();long count,total;
        try(PreparedStatement s=query(c,base+"SELECT count(*),coalesce(sum(points),0) FROM rows",args);ResultSet r=s.executeQuery()){r.next();count=r.getLong(1);total=r.getLong(2);}
        int pages=(int)Math.max(1,(count+23)/24),page=Math.min(Integer.parseInt(p.get("page")),pages);
        String order=p.get("sort").equals("highest")?"points DESC,created_at DESC":p.get("sort").equals("oldest")?"created_at ASC":"created_at DESC";
        JsonArray entries=new JsonArray();
        try(PreparedStatement s=query(c,base+"SELECT category,title,points,created_at,occurrences,source_type,source_key FROM rows ORDER BY "+order+",category,title,points LIMIT 24 OFFSET "+((page-1)*24),args);ResultSet r=s.executeQuery()) {
            while(r.next()){JsonObject e=new JsonObject();e.addProperty("category",r.getString(1));e.addProperty("title",r.getString(2));e.addProperty("points",r.getLong(3));e.addProperty("at",r.getTimestamp(4).toInstant().toString());e.addProperty("occurrences",r.getLong(5));e.addProperty("sourceType",r.getString(6));e.addProperty("sourceKey",r.getString(7));entries.add(e);}
        }
        result.addProperty("player",name);result.addProperty("count",count);result.addProperty("total",total);result.addProperty("page",page);result.addProperty("pages",pages);result.add("entries",entries);
        if(p.get("category").equals("Drops"))result.add("availableDrops",dropRewards(c,member,p.get("search"),p.get("sort")));
        result.add("availableRewards",RewardCatalog.read(c,member,p.get("category"),p.get("search"),p.get("sort")));
        return result;
    }
    static JsonArray dropRewards(Connection c,UUID member,String search,String sort)throws SQLException {
        JsonArray rewards=new JsonArray();
        // Read current enabled server policy, not historical awards or hardcoded prices.
        // Collapse identical NPC phase rules into a single item card.
        String sql="WITH earned AS (SELECT coalesce(e.type,'MANUAL') AS type,coalesce(e.event_key,m.event_key) AS event_key,count(*) AS occurrences,sum(l.points) AS earned_points FROM ledger l LEFT JOIN events e ON e.id=l.event_id LEFT JOIN manual_rewards m ON m.id=l.reward_id WHERE l.member_id=? GROUP BY coalesce(e.type,'MANUAL'),coalesce(e.event_key,m.event_key)) SELECT rule.type,coalesce(nullif(rule.display_name,''),rule.event_key) AS title,rule.points,rule.daily_limit,min(rule.event_key) AS source_key,coalesce(sum(earned.occurrences),0),coalesce(sum(earned.earned_points),0) FROM rules rule LEFT JOIN earned ON earned.type=rule.type AND earned.event_key=rule.event_key WHERE rule.enabled AND (rule.category='Drops' OR (rule.category='' AND rule.type='LOOT')) AND strpos(lower(coalesce(nullif(rule.display_name,''),rule.event_key)),lower(?))>0 GROUP BY rule.type,coalesce(nullif(rule.display_name,''),rule.event_key),rule.points,rule.daily_limit ORDER BY "+(sort.equals("highest")?"points DESC,title":"title,points DESC")+",rule.type,source_key LIMIT 1000";
        try(PreparedStatement s=query(c,sql,member,search);ResultSet r=s.executeQuery()) {
            while(r.next()) {
                JsonObject item=new JsonObject();item.addProperty("sourceType",r.getString(1));item.addProperty("title",r.getString(2));
                item.addProperty("points",r.getInt(3));item.addProperty("dailyLimit",r.getInt(4));item.addProperty("sourceKey",r.getString(5));item.addProperty("category","Drops");
                item.addProperty("receivedCount",r.getLong(6));item.addProperty("earnedPoints",r.getLong(7));item.addProperty("received",r.getLong(6)>0);
                item.addProperty("capScope",BalancedRewards.sharedItem(r.getString(1),r.getString(5))==null?"source":"item");
                if(BalancedRewards.barrows(r.getString(1),r.getString(5)))item.addProperty("familyDailyLimit",BalancedRewards.BARROWS_DAILY_LIMIT);
                rewards.add(item);
            }
        }
        return rewards;
    }
}

package com.traphouse.server;

import com.google.gson.JsonObject;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.time.Duration;
import java.time.Instant;
import java.util.Locale;
import java.util.UUID;

final class Policy {
    static final class Rejected extends RuntimeException {
        final int status;
        Rejected(int status, String message) { super(message); this.status = status; }
    }

    static String text(JsonObject object, String key, int max) {
        if (!object.has(key) || !object.get(key).isJsonPrimitive() || !object.getAsJsonPrimitive(key).isString()) {
            throw new Rejected(400, "Missing string: " + key);
        }
        String text = object.get(key).getAsString().trim();
        if (text.isEmpty() || text.length() > max || text.chars().anyMatch(Character::isISOControl)) {
            throw new Rejected(400, "Invalid field: " + key);
        }
        return text;
    }

    static String normalize(String name) {
        return name.replace('\u00a0', ' ').trim().toLowerCase(Locale.ROOT).replaceAll("\\s+", " ");
    }

    static UUID uuid(String value) {
        try {
            UUID id = UUID.fromString(value);
            if (!id.toString().equalsIgnoreCase(value)) throw new IllegalArgumentException();
            return id;
        } catch (IllegalArgumentException invalid) { throw new Rejected(400, "Invalid UUID"); }
    }

    static Instant observed(String value, Instant now) {
        try {
            Instant time = Instant.parse(value);
            if (time.isBefore(now.minus(Duration.ofHours(24))) || time.isAfter(now.plusSeconds(300))) {
                throw new Rejected(422, "Observation outside accepted time window");
            }
            return time;
        } catch (java.time.format.DateTimeParseException invalid) { throw new Rejected(400, "Invalid time"); }
    }

    static void observationType(String type) {
        if (!type.equals("LOOT") && !type.equals("COMBAT") && !type.equals("COLLECTION")) {
            throw new Rejected(400, "Unsupported event type");
        }
    }

    static void independentReviewer(boolean administrator, UUID actor, UUID recipient) {
        if (!administrator) throw new Rejected(403, "Administrator required");
        if (actor.equals(recipient)) throw new Rejected(403, "A different administrator must review this reward");
    }

    static String hash(String token) {
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256").digest(token.getBytes(StandardCharsets.UTF_8));
            StringBuilder hex = new StringBuilder();
            for (byte b : digest) hex.append(String.format("%02x", b & 255));
            return hex.toString();
        } catch (java.security.NoSuchAlgorithmException impossible) { throw new IllegalStateException(impossible); }
    }
}

package com.traphouse.server;

import com.google.gson.*;
