/** Owner-only editor data; display ranks never grant API permissions. */
final class RankManagement {
    static JsonObject read(Connection c,Actor actor)throws SQLException {
        RankSecurity.owner(actor);
        JsonObject data=new JsonObject();data.addProperty("ownerId",actor.id.toString());
        JsonArray members=new JsonArray();
        try(PreparedStatement s=query(c,"SELECT m.id,m.name,s.assigned_rank,coalesce(s.locked,false) FROM members m LEFT JOIN member_rank_state s ON s.member_id=m.id WHERE m.active ORDER BY m.normalized_name,m.id");ResultSet r=s.executeQuery()) {
            while(r.next()){JsonObject member=new JsonObject();member.addProperty("id",r.getString(1));member.addProperty("name",r.getString(2));member.addProperty("assignedRank",RankSecurity.canonicalRank(c,r.getString(3)));member.addProperty("locked",r.getBoolean(4));members.add(member);}
        }
        data.add("members",members);return data;
    }
    static void initializeOwnerRanks(Connection c)throws SQLException {
        try(Statement s=c.createStatement()){s.execute("SELECT pg_advisory_xact_lock(72419051001)");}
        try(PreparedStatement s=query(c,"SELECT 1 FROM configuration_migrations WHERE name='owner-display-rank-v1'");ResultSet r=s.executeQuery()){if(r.next())return;}
        try(PreparedStatement s=query(c,"SELECT m.id FROM members m JOIN member_permissions p ON p.member_id=m.id LEFT JOIN member_rank_state state ON state.member_id=m.id WHERE m.active AND p.permission='OWNER' AND state.assigned_rank IS NULL FOR UPDATE OF m");ResultSet r=s.executeQuery()) {
            while(r.next())assignOwner(c,r.getObject(1,java.util.UUID.class));
        }
        execute(c,"INSERT INTO configuration_migrations(name) VALUES ('owner-display-rank-v1')");
    }
    static void assignOwner(Connection c,java.util.UUID member)throws SQLException {
        execute(c,"INSERT INTO member_rank_state(member_id,assigned_rank,locked) VALUES (?,'Owner',true) ON CONFLICT(member_id) DO UPDATE SET assigned_rank='Owner',locked=true",member);
        JsonObject details=new JsonObject();details.addProperty("source","server operator owner provisioning");details.addProperty("rank","Owner");
        RankSecurity.audit(c,new Actor(member,"",RankSecurity.Role.OWNER),"OWNER_DISPLAY_RANK_INITIALIZED",member,details);
    }
}

package com.traphouse.server;

import com.google.gson.*;
import java.sql.*;
import java.util.UUID;
import static com.traphouse.server.RankingStore.*;

/** Application ranks are independent of OSRS ranks and of API permissions. */
final class RankSecurity {
    enum Role { OWNER, ADMINISTRATOR, EVENT_MANAGER, MEMBER }

    static void owner(Actor actor) {
        if (actor.role != Role.OWNER) throw new Policy.Rejected(403,"Owner required");
    }
    static void rankPermission(Actor actor, boolean protectedRank, boolean locked) {
        if (actor.role == Role.OWNER) return;
        if (actor.role != Role.ADMINISTRATOR || protectedRank || locked)
            throw new Policy.Rejected(403,"Owner required for protected or locked ranks; otherwise administrator required");
    }
    static void adjustmentPermission(Actor actor,int delta) {
        if(delta<0)owner(actor);
        else if(!actor.admin)throw new Policy.Rejected(403,"Administrator required to award points");
    }
    static void demotionPermission(Actor actor,String previous,String next,long previousThreshold,long nextThreshold) {
        if(!previous.equals(next) && !previous.equals("Unranked")
            && (previousThreshold<0 || nextThreshold<0 || nextThreshold<previousThreshold))owner(actor);
    }
    static boolean eligible(String automatic, String assigned, boolean locked, boolean protectedRank, long automaticThreshold, long assignedThreshold) {
        return !locked && !protectedRank && !automatic.equals("Unranked") && !automatic.equals(assigned)
            && (assigned == null || automaticThreshold > assignedThreshold);
    }
    static boolean protectedRank(Connection c,String rank) throws SQLException {
        if (rank == null) return false;
        try (PreparedStatement s=query(c,"SELECT 1 FROM protected_ranks p LEFT JOIN rank_aliases a ON a.legacy_name=p.name WHERE coalesce(a.rank_name,p.name)=? OR p.name=?",rank,rank); ResultSet r=s.executeQuery()) { return r.next(); }
    }
    static String canonicalRank(Connection c,String rank)throws SQLException {
        if(rank==null)return null;
        try(PreparedStatement s=query(c,"SELECT rank_name FROM rank_aliases WHERE legacy_name=?",rank);ResultSet r=s.executeQuery()){return r.next()?r.getString(1):rank;}
    }
    static long threshold(Connection c,String rank) throws SQLException {
        if(rank==null)return -1;
        rank=canonicalRank(c,rank);
        try(PreparedStatement s=query(c,"SELECT threshold FROM ranks WHERE name=?",rank);ResultSet r=s.executeQuery()){return r.next()?r.getLong(1):-1;}
    }
    static void enrich(Connection c,UUID member,JsonObject profile) throws SQLException {
        long points,lifetimeEarned;
        try(PreparedStatement s=query(c,"SELECT coalesce(sum(points),0),coalesce(sum(points) FILTER(WHERE points>0),0) FROM point_entries WHERE member_id=?",member);ResultSet r=s.executeQuery()){r.next();points=r.getLong(1);lifetimeEarned=r.getLong(2);}
        String automatic="Unranked", balanceRank="Unranked", assigned=null; long autoThreshold=-1; boolean locked=false;
        try(PreparedStatement s=query(c,"SELECT name,threshold FROM ranks WHERE threshold<=? AND name NOT IN (SELECT name FROM protected_ranks) AND name NOT IN (SELECT legacy_name FROM rank_aliases) ORDER BY threshold DESC LIMIT 1",points);ResultSet r=s.executeQuery()) {
            if(r.next())balanceRank=r.getString(1);
        }
        try(PreparedStatement s=query(c,"SELECT rank,threshold FROM retained_automatic_ranks WHERE member_id=?",member);ResultSet r=s.executeQuery()) {
            if(r.next()){automatic=r.getString(1);autoThreshold=r.getLong(2);}
        }
        try(PreparedStatement s=query(c,"SELECT assigned_rank,locked FROM member_rank_state WHERE member_id=?",member);ResultSet r=s.executeQuery()) {
            if(r.next()){assigned=canonicalRank(c,r.getString(1));locked=r.getBoolean(2);}
        }
        boolean protection=protectedRank(c,assigned);
        profile.addProperty("points",points);
        profile.addProperty("lifetimeEarnedPoints",lifetimeEarned);
        profile.addProperty("automaticRank",automatic);
        profile.addProperty("automaticRankThreshold",autoThreshold);
        profile.addProperty("balanceRank",balanceRank);
        JsonArray earned=new JsonArray();
        try(PreparedStatement s=query(c,"SELECT coalesce(a.rank_name,h.rank),h.threshold,h.points_at_earning,h.earned_at,h.rank FROM earned_rank_history h LEFT JOIN rank_aliases a ON a.legacy_name=h.rank WHERE h.member_id=? ORDER BY h.earned_at,h.threshold,h.rank",member);ResultSet r=s.executeQuery()) {
            while(r.next()){JsonObject row=new JsonObject();row.addProperty("rank",r.getString(1));row.addProperty("threshold",r.getLong(2));row.addProperty("pointsAtEarning",r.getLong(3));row.addProperty("at",r.getTimestamp(4).toInstant().toString());row.addProperty("originalRank",r.getString(5));earned.add(row);}
        }
        profile.add("earnedRankHistory",earned);
        profile.addProperty("assignedRank",assigned);
        profile.addProperty("rank",assigned==null?automatic:assigned);
        profile.addProperty("rankLocked",locked);
        profile.addProperty("protectedRank",protection);
        profile.addProperty("promotionEligible",eligible(automatic,assigned,locked,protection,autoThreshold,threshold(c,assigned)));
    }
    static void audit(Connection c,Actor actor,String action,UUID target,JsonObject details) throws SQLException {
        execute(c,"INSERT INTO audit(actor,action,target,details) VALUES (?,?,?,?::jsonb)",actor.id,action,target,details.toString());
    }
    static JsonObject changeRank(Connection c,Actor actor,UUID member,JsonObject body) throws SQLException {
        // Reject unprivileged callers before looking up any target state.
        rankPermission(actor,false,false);
        String action=Policy.text(body,"action",10);
        String reason=Policy.text(body,"reason",1000);
        if(!java.util.Set.of("ASSIGN","REMOVE","LOCK","UNLOCK").contains(action))throw new Policy.Rejected(400,"Invalid rank action");
        if(action.equals("LOCK")||action.equals("UNLOCK"))owner(actor);
        lockMember(c,member);
        JsonObject before=new JsonObject();enrich(c,member,before);
        String current=before.has("assignedRank")&&!before.get("assignedRank").isJsonNull()?before.get("assignedRank").getAsString():null;
        String rank=action.equals("ASSIGN")?canonicalRank(c,Policy.text(body,"rank",40)):current;
        rankPermission(actor,protectedRank(c,current)||protectedRank(c,rank),before.get("rankLocked").getAsBoolean());
        if(action.equals("ASSIGN")&&!protectedRank(c,rank)&&threshold(c,rank)<0)throw new Policy.Rejected(422,"Unknown rank");
        if(action.equals("REMOVE"))rank=null;
        boolean locked=before.get("rankLocked").getAsBoolean();
        if(action.equals("LOCK")) { locked=true; if(rank==null)rank=before.get("automaticRank").getAsString(); }
        if(action.equals("UNLOCK"))locked=false;
        String previous=before.get("rank").getAsString();
        String effective=rank==null?before.get("automaticRank").getAsString():rank;
        demotionPermission(actor,previous,effective,current==null?before.get("automaticRankThreshold").getAsLong():threshold(c,current),rank==null?before.get("automaticRankThreshold").getAsLong():threshold(c,rank));
        execute(c,"INSERT INTO member_rank_state(member_id,assigned_rank,locked) VALUES (?,?,?) ON CONFLICT(member_id) DO UPDATE SET assigned_rank=excluded.assigned_rank,locked=excluded.locked",member,rank,locked);
        JsonObject after=new JsonObject();enrich(c,member,after);
        JsonObject details=new JsonObject();details.add("before",before);details.add("after",after);details.addProperty("reason",reason);
        audit(c,actor,"RANK_"+action,member,details);
        return after;
    }
    static JsonObject adjust(Connection c,Actor actor,UUID member,JsonObject body) throws SQLException {
        if(!actor.admin)throw new Policy.Rejected(403,"Administrator required");
        UUID id=Policy.uuid(Policy.text(body,"id",36));String reason=Policy.text(body,"reason",1000);
        if(!body.has("points")||!body.get("points").isJsonPrimitive()||!body.getAsJsonPrimitive("points").isNumber())
            throw new Policy.Rejected(400,"Integer points required");
        int delta;
        try { delta=body.get("points").getAsBigDecimal().intValueExact(); }
        catch(RuntimeException invalid){throw new Policy.Rejected(400,"Integer points required");}
        if(delta==0||delta>100000||delta< -100000)throw new Policy.Rejected(400,"Adjustment must be between -100000 and 100000 and nonzero");
        adjustmentPermission(actor,delta);
        lockMember(c,member);
        try(PreparedStatement s=query(c,"SELECT member_id,actor,points,reason FROM point_adjustments WHERE id=?",id);ResultSet r=s.executeQuery()) {
            if(r.next()) {
                if(!member.equals(r.getObject(1,UUID.class))||!actor.id.equals(r.getObject(2,UUID.class))||delta!=r.getInt(3)||!reason.equals(r.getString(4)))throw new Policy.Rejected(409,"Adjustment ID reused");
                return result(id.toString(),"DUPLICATE",delta);
            }
        }
        JsonObject before=new JsonObject();enrich(c,member,before);
        if(before.get("points").getAsLong()+delta<0)throw new Policy.Rejected(422,"Points cannot become negative");
        execute(c,"INSERT INTO point_adjustments(id,member_id,points,actor,reason) VALUES (?,?,?,?,?)",id,member,delta,actor.id,reason);
        // The database insertion trigger permanently audits the adjustment with both identities.
        return result(id.toString(),"ADJUSTED",delta);
    }
    static JsonObject permission(Connection c,Actor actor,UUID member,JsonObject body)throws SQLException {
        owner(actor);Role role;
        try{role=Role.valueOf(Policy.text(body,"permission",20));}catch(IllegalArgumentException invalid){throw new Policy.Rejected(400,"Invalid permission");}
        // Owner identities are bootstrapped locally, never delegated through the API.
        if(role==Role.OWNER)throw new Policy.Rejected(403,"Owner provisioning requires the server operator");
        lockMember(c,member);
        try(PreparedStatement s=query(c,"SELECT permission FROM member_permissions WHERE member_id=?",member);ResultSet r=s.executeQuery()) {
            if(r.next()&&r.getString(1).equals("OWNER"))throw new Policy.Rejected(403,"Owner permissions require the server operator");
        }
        String reason=Policy.text(body,"reason",1000);
        execute(c,"INSERT INTO member_permissions VALUES (?,?) ON CONFLICT(member_id) DO UPDATE SET permission=excluded.permission",member,role.name());
        JsonObject details=new JsonObject();details.addProperty("permission",role.name());details.addProperty("reason",reason);audit(c,actor,"PERMISSION_CHANGED",member,details);return details;
    }
    static JsonArray auditLog(Connection c,Actor actor,long after)throws SQLException {
        if(!actor.admin)throw new Policy.Rejected(403,"Administrator required");
        JsonArray entries=new JsonArray();
        try(PreparedStatement s=query(c,"SELECT id,actor,action,target,created_at,details FROM audit WHERE id>? ORDER BY id LIMIT 200",after);ResultSet r=s.executeQuery()) {
            while(r.next()){JsonObject row=new JsonObject();row.addProperty("id",r.getLong(1));row.addProperty("actor",r.getString(2));row.addProperty("action",r.getString(3));row.addProperty("target",r.getString(4));row.addProperty("at",r.getTimestamp(5).toInstant().toString());row.add("details",JsonParser.parseString(r.getString(6)));entries.add(row);}
        }return entries;
    }
    /** Periodic reconciliation also catches threshold edits and promotions earned while offline. */
    static void promotions(DiscordWorker.Connections connections) {
        try(Connection c=connections.open()) {
            c.setAutoCommit(false);
            execute(c,"SET LOCAL statement_timeout='10s'");
            execute(c,"WITH candidates AS (SELECT m.id AS member_id,a.name AS rank FROM members m "
                + "LEFT JOIN member_rank_state s ON s.member_id=m.id "
                + "LEFT JOIN rank_aliases labels ON labels.legacy_name=s.assigned_rank LEFT JOIN ranks assigned ON assigned.name=coalesce(labels.rank_name,s.assigned_rank) "
                + "CROSS JOIN LATERAL (SELECT rank AS name,threshold FROM retained_automatic_ranks WHERE member_id=m.id "
                + "ORDER BY threshold DESC LIMIT 1) a "
                + "WHERE m.active AND NOT coalesce(s.locked,false) AND NOT EXISTS (SELECT 1 FROM protected_ranks p WHERE p.name=coalesce(labels.rank_name,s.assigned_rank)) "
                + "AND (s.assigned_rank IS NULL OR a.threshold>coalesce(assigned.threshold,-1))), "
                + "notices AS (INSERT INTO promotion_notices SELECT member_id,rank FROM candidates WHERE true ON CONFLICT DO NOTHING RETURNING member_id,rank) "
                + "INSERT INTO discord_outbox(id,content) SELECT gen_random_uuid(),m.name || ' qualifies for promotion to ' || n.rank || '. Leadership review required; in-game ranks are changed manually.' FROM notices n JOIN members m ON m.id=n.member_id");
            c.commit();
        }catch(SQLException unavailable){System.err.println("Promotion reconciliation unavailable; will retry.");}
    }

    static JsonObject publishEvent(Connection c,Actor actor,UUID event,JsonObject body)throws SQLException {
        if(actor.role==Role.MEMBER)throw new Policy.Rejected(403,"Event manager required");
        if(!body.has("published")||!body.get("published").isJsonPrimitive()||!body.getAsJsonPrimitive("published").isBoolean())throw new Policy.Rejected(400,"Boolean published required");
        boolean published=body.get("published").getAsBoolean();
        try(PreparedStatement s=query(c,"UPDATE clan_events SET published=? WHERE id=?",published,event)) {
            if(s.executeUpdate()==0)throw new Policy.Rejected(404,"Event not found");
        }
        JsonObject details=new JsonObject();details.addProperty("published",published);audit(c,actor,"EVENT_PUBLISHED",event,details);return details;
    }
}

package com.traphouse.server;

import com.google.gson.*;
import com.sun.net.httpserver.*;
import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.security.SecureRandom;
import java.sql.*;
import java.time.Instant;
import java.util.*;
import java.util.concurrent.*;

/** Deploy behind an HTTPS reverse proxy with body/time/rate limits. */
public final class RankingServer {
    private static final Gson JSON = new Gson();
    private final DiscordWorker.Connections connections;
    private final DiscordLogin discordLogin;
    private final DiscordInteractions discordInteractions;
    private final Map<UUID, Window> windows = new HashMap<>();
    private static final class Window { long minute; int count; }

    RankingServer(DiscordWorker.Connections connections) { this.connections = connections; this.discordLogin=new DiscordLogin(connections);this.discordInteractions=new DiscordInteractions(connections,System.getenv()); }

    private synchronized void rateLimit(UUID member) {
        long minute = System.currentTimeMillis() / 60000;
        windows.entrySet().removeIf(e -> e.getValue().minute < minute - 1);
        Window window = windows.get(member);
        if (window == null) {
            if (windows.size() >= 10000) throw new Policy.Rejected(429, "Server busy");
            window = new Window(); windows.put(member, window);
        }
        if (window.minute != minute) { window.minute = minute; window.count = 0; }
        if (++window.count > 120) throw new Policy.Rejected(429, "Rate limit reached");
    }

    void handle(HttpExchange exchange) throws IOException {
        if(exchange.getRequestURI().getPath().equals("/discord/interactions")){discordInteractions.handle(exchange);return;}
        if(DiscordLogin.matches(exchange.getRequestURI().getPath())) { discordLogin.handle(exchange); return; }
        int status = 200;
        JsonElement result;
        try {
            String method = exchange.getRequestMethod();
            String path = exchange.getRequestURI().getPath();
            if ("GET".equals(method) && "/health".equals(path)) {
                JsonObject health = new JsonObject(); health.addProperty("status", "ok"); result = health;
            } else if ("GET".equals(method) && "/ready".equals(path)) {
                try (Connection c = connections.open(); Statement s = c.createStatement()) {
                    s.executeQuery("SELECT 1 FROM members LIMIT 1").close();
                }
                JsonObject health = new JsonObject(); health.addProperty("status", "ready"); result = health;
            } else {
                JsonObject body = "POST".equals(method) ? readBody(exchange) : new JsonObject();
                try (Connection c = connections.open()) {
                    c.setAutoCommit(false);
                    try {
                        RankingStore.execute(c, "SET LOCAL statement_timeout='10s'");
                        RankingStore.execute(c, "SET LOCAL lock_timeout='5s'");
                        RankingStore.Actor actor = RankingStore.authenticate(c, exchange.getRequestHeaders().getFirst("Authorization"));
                        rateLimit(actor.id);
                        result = route(c, actor, method, path, exchange.getRequestURI().getRawQuery(), body);
                        c.commit();
                    } catch (Exception failure) { c.rollback(); throw failure; }
                }
            }
        } catch (Policy.Rejected rejection) {
            status = rejection.status; result = error(rejection.getMessage());
        } catch (JsonParseException | IllegalStateException | IllegalArgumentException malformed) {
            status = 400; result = error("Malformed request");
        } catch (Exception failure) {
            // Never log request headers, tokens, webhook URLs, SQL text, or database credentials.
            System.err.println("Ranking request failed: " + failure.getClass().getSimpleName());
            status = 503; result = error("Service unavailable; retry with the same request ID");
        }
        byte[] bytes = JSON.toJson(result).getBytes(StandardCharsets.UTF_8);
        exchange.getResponseHeaders().set("Content-Type", "application/json; charset=utf-8");
        exchange.getResponseHeaders().set("Cache-Control", "no-store");
        exchange.getResponseHeaders().set("X-Content-Type-Options", "nosniff");
        if (status == 429) exchange.getResponseHeaders().set("Retry-After", "60");
        exchange.sendResponseHeaders(status, bytes.length);
        try (OutputStream output = exchange.getResponseBody()) { output.write(bytes); }
        finally { exchange.close(); }
    }

    static JsonObject readBody(HttpExchange exchange) throws IOException {
        String contentType = exchange.getRequestHeaders().getFirst("Content-Type");
        if (contentType == null || !contentType.toLowerCase(Locale.ROOT).matches("application/json(?:;.*)?")) {
            throw new Policy.Rejected(415, "application/json required");
        }
        byte[] bytes = exchange.getRequestBody().readNBytes(16385);
        if (bytes.length > 16384) throw new Policy.Rejected(413, "Request too large");
        JsonElement parsed = JsonParser.parseString(new String(bytes, StandardCharsets.UTF_8));
        if (!parsed.isJsonObject()) throw new Policy.Rejected(400, "JSON object required");
        return parsed.getAsJsonObject();
    }

    static JsonElement route(Connection c, RankingStore.Actor actor, String method, String path, String query, JsonObject body) throws SQLException {
        if(method.equals("POST")&&path.matches("/v1/admin/members/[0-9a-fA-F-]{36}/(rank|points|permission)")) {
            String[] parts=path.split("/"); UUID member=Policy.uuid(parts[4]);
            if(parts[5].equals("rank"))return RankSecurity.changeRank(c,actor,member,body);
            if(parts[5].equals("points"))return RankSecurity.adjust(c,actor,member,body);
            return RankSecurity.permission(c,actor,member,body);
        }
        if(method.equals("POST")&&path.matches("/v1/admin/clan-events/[0-9a-fA-F-]{36}/publish"))
            return RankSecurity.publishEvent(c,actor,Policy.uuid(path.split("/")[4]),body);
        if(method.equals("GET")&&path.equals("/v1/admin/audit")) {
            long after=0;
            if(query!=null) {
                if(!query.matches("after=[0-9]{1,18}"))throw new Policy.Rejected(400,"Expected after audit ID");
                after=Long.parseLong(query.substring(6));
            }
            return RankSecurity.auditLog(c,actor,after);
        }
        if(method.equals("GET")&&path.equals("/v1/point-notifications"))return PointNotifications.read(c,actor,query);
        if(method.equals("GET")&&path.equals("/v1/points-log"))return PointsLog.read(c,query);
        if(method.equals("GET")&&path.equals("/v1/members"))return ClanFeatures.member(c,playerQuery(query));
        if(method.equals("POST")&&path.equals("/v1/progress"))return ClanFeatures.sync(c,actor,body);
        if(method.equals("POST")&&path.matches("/v1/clan-events/[0-9a-fA-F-]{36}/(register|cancel)")) {
            String[] parts=path.split("/");return ClanFeatures.register(c,actor,Policy.uuid(parts[3]),parts[4].equals("register"));
        }
        if (method.equals("GET") && path.equals("/v1/dashboard")) return RankingStore.dashboard(c, actor, playerQuery(query));
        if (method.equals("POST") && path.equals("/v1/events")) return RankingStore.event(c, actor, body);
        if (method.equals("POST") && path.equals("/v1/manual-rewards")) return RankingStore.requestReward(c, actor, body);
        if (method.equals("GET") && path.equals("/v1/admin/rewards")) return RankingStore.pending(c, actor);
        if (method.equals("POST") && path.matches("/v1/admin/rewards/[0-9a-fA-F-]{36}/(approve|reject)")) {
            String[] parts = path.split("/");
            return RankingStore.review(c, actor, Policy.uuid(parts[4]), parts[5].equals("approve"));
        }
        throw new Policy.Rejected(404, "Unknown API route");
    }

    static String playerQuery(String query) {
        if (query == null || query.length() > 200 || !query.startsWith("player=") || query.contains("&")) {
            throw new Policy.Rejected(400, "Exactly one player parameter required");
        }
        String player = URLDecoder.decode(query.substring(7), StandardCharsets.UTF_8);
        if (player.isEmpty() || player.length() > 12) throw new Policy.Rejected(400, "Invalid character name");
        return player;
    }

    private static JsonObject error(String message) { JsonObject error = new JsonObject(); error.addProperty("error", message); return error; }

    static Connection connect() throws SQLException {
        return new ServerConfig(System.getenv()).connect();
    }

    public static void main(String[] args) throws Exception {
        if (args.length > 0) { command(args); return; }
        // Fail fast before accepting traffic; migrations are a separate explicit deployment step.
        try (Connection c = connect(); Statement s = c.createStatement()) { s.executeQuery("SELECT 1 FROM members LIMIT 1").close(); }
        RankingServer service = new RankingServer(RankingServer::connect);
        ServerConfig config = new ServerConfig(System.getenv());
        int port = config.port;
        HttpServer server = HttpServer.create(new InetSocketAddress(config.bindAddress, port), 64);
        ThreadPoolExecutor pool = new ThreadPoolExecutor(8, 8, 0, TimeUnit.SECONDS, new ArrayBlockingQueue<>(64));
        server.setExecutor(pool);
        server.createContext("/", service::handle);
        ScheduledExecutorService notifications = Executors.newSingleThreadScheduledExecutor();
        notifications.scheduleWithFixedDelay(() -> RankSecurity.promotions(RankingServer::connect),10,30,TimeUnit.SECONDS);
        String webhook = System.getenv("TRAP_DISCORD_WEBHOOK");
        if (webhook != null && !webhook.isBlank()) notifications.scheduleWithFixedDelay(new DiscordWorker(RankingServer::connect, webhook), 5, 5, TimeUnit.SECONDS);
        String bot=System.getenv("TRAP_DISCORD_BOT_TOKEN");
        if(bot!=null&&!bot.isBlank())notifications.scheduleWithFixedDelay(new DiscordJoinBot(RankingServer::connect,System.getenv()),5,5,TimeUnit.SECONDS);
        if(!"false".equalsIgnoreCase(System.getenv("TRAP_WOM_STATS_ENABLED")))notifications.scheduleWithFixedDelay(new WiseOldManStats(RankingServer::connect),15,30,TimeUnit.SECONDS);
        Runtime.getRuntime().addShutdownHook(new Thread(() -> { server.stop(2); pool.shutdownNow(); notifications.shutdownNow(); }));
        server.start();
        System.out.println("TRAP HOUSE ranking API listening on port " + port);
    }

    static String verifiedName(String value) {
        String name = value.trim();
        if (!name.matches("[A-Za-z0-9 _-]{1,12}")) throw new IllegalArgumentException("Invalid character name");
        return name;
    }

    static void command(String[] args) throws Exception {
        command(args, RankingServer::connect);
    }

    static void command(String[] args, DiscordWorker.Connections connections) throws Exception {
        if(args.length==1&&args[0].equals("init")){DatabaseInitialization.run(connections);System.out.println("Schema initialized.");return;}
        if(args.length==1&&args[0].equals("discord-setup")){new DiscordJoinBot(connections,System.getenv()).setup();System.out.println("Discord commands registered and Link RuneLite button posted.");return;}
        if(args.length==1&&args[0].equals("discord-commands")){new DiscordJoinBot(connections,System.getenv()).setup(false);System.out.println("Discord link commands registered. No new button message posted.");return;}
        if(args.length==1&&args[0].equals("discord-clean-reviews")){int queued=new DiscordJoinBot(connections,System.getenv()).cleanReviewedMessages();System.out.println("Queued "+queued+" reviewed link messages. The worker will copy each decision to the staff log before removing its review message.");return;}
        if (args.length == 2 && args[0].equals("add-member")) verifiedName(args[1]);
        if(args.length==4&&args[0].equals("correct-member-name")) {
            verifiedName(args[1]);verifiedName(args[2]);
            if(args[3].trim().length()<10||args[3].length()>1000)throw new IllegalArgumentException("Give a correction reason of 10–1000 characters");
        }
        try (Connection c = connections.open()) {
            c.setAutoCommit(false);
            if(args.length==4&&args[0].equals("correct-member-name")) {
                String oldName=verifiedName(args[1]),newName=verifiedName(args[2]);UUID member;String storedName;
                try(PreparedStatement s=RankingStore.query(c,"SELECT id,name FROM members WHERE normalized_name=? AND active FOR UPDATE",Policy.normalize(oldName));ResultSet r=s.executeQuery()) {
                    if(!r.next())throw new IllegalArgumentException("Original active member not found; no correction made");
                    member=r.getObject(1,UUID.class);storedName=r.getString(2);
                }
                try(PreparedStatement s=RankingStore.query(c,"SELECT id FROM members WHERE normalized_name=? AND id<>?",Policy.normalize(newName),member);ResultSet r=s.executeQuery()) {
                    if(r.next())throw new IllegalArgumentException("Correct name already has a member record; operator review is required. No records were merged");
                }
                String discord;
                try(PreparedStatement s=RankingStore.query(c,"SELECT discord_user_id FROM discord_member_links WHERE member_id=? FOR UPDATE",member);ResultSet r=s.executeQuery()) {
                    if(!r.next())throw new IllegalArgumentException("Original member has no Discord link; no correction made");
                    discord=r.getString(1);
                }
                RankingStore.execute(c,"UPDATE members SET name=?,normalized_name=? WHERE id=?",newName,Policy.normalize(newName),member);
                RankingStore.execute(c,"UPDATE credentials SET revoked=true WHERE member_id=? AND NOT revoked",member);
                RankingStore.execute(c,"DELETE FROM discord_login_sessions WHERE member_id=?",member);
                JsonObject details=new JsonObject();details.addProperty("source","server operator CLI");
                details.addProperty("oldName",storedName);details.addProperty("newName",newName);
                details.addProperty("discordUserId",discord);details.addProperty("reason",args[3].trim());
                operatorAudit(c,member,"MEMBER_NAME_CORRECTED",details);
                c.commit();
                System.out.println("Corrected "+storedName+" to "+newName+". Member UUID, Discord link, points and history preserved. Old credentials revoked; sign in with Discord again.");return;
            }
            if(args.length==3&&args[0].equals("link-discord")) {
                String name=verifiedName(args[1]), discord=DiscordLogin.snowflake(args[2]);
                UUID member;
                try(PreparedStatement s=RankingStore.query(c,"SELECT id FROM members WHERE normalized_name=? AND active FOR UPDATE",Policy.normalize(name));ResultSet r=s.executeQuery()) {
                    if(!r.next())throw new IllegalArgumentException("Add and independently verify an active member first");member=r.getObject(1,UUID.class);
                }
                // Unique constraints reject relinking either identity. Never silently replace an existing link.
                RankingStore.execute(c,"INSERT INTO discord_member_links(discord_user_id,member_id) VALUES (?,?) ON CONFLICT DO NOTHING",discord,member);
                try(PreparedStatement s=RankingStore.query(c,"SELECT 1 FROM discord_member_links WHERE discord_user_id=? AND member_id=?",discord,member);ResultSet r=s.executeQuery()) {
                    if(!r.next())throw new IllegalArgumentException("An identity is already linked; review and revoke the old link first");
                }
                JsonObject details=new JsonObject();details.addProperty("source","server operator CLI");details.addProperty("discordUserId",discord);
                operatorAudit(c,member,"DISCORD_IDENTITY_LINKED",details);
                c.commit();System.out.println("Discord identity linked to the verified member. No permissions changed.");return;
            }
            if (args.length == 2 && args[0].equals("add-member")) {
                // Operator-only onboarding, after independently verifying membership and character ownership.
                String name = verifiedName(args[1]);
                UUID proposed = UUID.randomUUID();
                boolean created;
                try (PreparedStatement s = RankingStore.query(c,
                    "INSERT INTO members(id,name,normalized_name) VALUES (?,?,?) ON CONFLICT(normalized_name) DO NOTHING",
                    proposed, name, Policy.normalize(name))) { created = s.executeUpdate() == 1; }
                UUID member;
                try (PreparedStatement s = RankingStore.query(c, "SELECT id,active FROM members WHERE normalized_name=? FOR UPDATE", Policy.normalize(name));
                     ResultSet r = s.executeQuery()) {
                    if (!r.next() || !r.getBoolean("active")) throw new IllegalArgumentException("Member is inactive; review roster before reactivating");
                    member = r.getObject("id", UUID.class);
                }
                if (created) {
                    JsonObject details = new JsonObject();
                    details.addProperty("source", "server operator CLI");
                    details.addProperty("memberName", name);
                    operatorAudit(c,member,"MEMBER_PROVISIONED",details);
                }
                c.commit();
                System.out.println("Verified member UUID: " + member);
                return;
            }
            if(args.length==2&&args[0].equals("bootstrap-owner")) {
                UUID member=Policy.uuid(args[1]);RankingStore.lockMember(c,member);
                RankingStore.execute(c,"INSERT INTO member_permissions VALUES (?,'OWNER') ON CONFLICT(member_id) DO UPDATE SET permission='OWNER'",member);
                RankManagement.assignOwner(c,member);
                JsonObject details=new JsonObject();details.addProperty("source","server operator CLI");
                RankSecurity.audit(c,new RankingStore.Actor(member,"",RankSecurity.Role.OWNER),"OWNER_BOOTSTRAPPED",member,details);
                c.commit();System.out.println("Owner permission and locked Owner display rank provisioned. Existing member credentials now use Owner permission.");return;
            }
            if (args.length == 3 && args[0].equals("issue-token") && (args[2].equals("member") || args[2].equals("admin"))) {
                String name = verifiedName(args[1]);
                // Staff must independently verify membership and ownership before issuing credentials.
                UUID member;
                try (PreparedStatement s = RankingStore.query(c, "SELECT id FROM members WHERE normalized_name=? AND active", Policy.normalize(name)); ResultSet r = s.executeQuery()) {
                    if (!r.next()) throw new IllegalArgumentException("Add and verify an active member before issuing a token");
                    member = r.getObject(1, UUID.class);
                }
                byte[] random = new byte[32]; new SecureRandom().nextBytes(random);
                String token = Base64.getUrlEncoder().withoutPadding().encodeToString(random);
                RankingStore.execute(c, "INSERT INTO credentials(token_hash,member_id,administrator,expires_at) VALUES (?,?,?,?)", Policy.hash(token), member, args[2].equals("admin"), Timestamp.from(Instant.now().plusSeconds(90L * 86400)));
                RankingStore.execute(c, "INSERT INTO audit(actor,action,target) VALUES (?,'CREDENTIAL_ISSUED',?)", member, member);
                c.commit();
                System.out.println("Credential (shown once; expires in 90 days): " + token); return;
            }
            throw new IllegalArgumentException("Commands: init | discord-setup | discord-commands | add-member <verified-character-name> | correct-member-name <old-name> <verified-correct-name> <reason> | link-discord <verified-character-name> <discord-user-id> | bootstrap-owner <verified-member-uuid> | issue-token <verified-character-name> member|admin");
        }
    }

    static void operatorAudit(Connection c, UUID member, String action, JsonObject details) throws SQLException {
        // Legacy audit.actor is a required member FK, including for bootstrap operations.
        // Explicit metadata distinguishes operator actions from authenticated member requests.
        details.addProperty("actorKind","SERVER_OPERATOR");
        details.addProperty("actorReference","affected member; operator command has no authenticated API actor");
        RankingStore.execute(c,"INSERT INTO audit(actor,action,target,details) VALUES (?,?,?,?::jsonb)",member,action,member,details.toString());
    }
}

package com.traphouse.server;

import com.google.gson.*;
import java.sql.*;
import java.time.Instant;
import java.util.UUID;

/** All mutations run in the caller's transaction. A member row lock serializes daily caps. */
final class RankingStore {
    static final class Actor {
        final UUID id;
        final String name;
        final boolean admin;
        final RankSecurity.Role role;
        Actor(UUID id, String name, boolean admin) { this(id,name,admin ? RankSecurity.Role.ADMINISTRATOR : RankSecurity.Role.MEMBER); }
        Actor(UUID id, String name, RankSecurity.Role role) { this.id=id; this.name=name; this.role=role; this.admin=role==RankSecurity.Role.OWNER || role==RankSecurity.Role.ADMINISTRATOR; }
    }

    static PreparedStatement query(Connection c, String sql, Object... args) throws SQLException {
        PreparedStatement statement = c.prepareStatement(sql);
        for (int i = 0; i < args.length; i++) statement.setObject(i + 1, args[i]);
        return statement;
    }

    static void execute(Connection c, String sql, Object... args) throws SQLException {
        try (PreparedStatement s = query(c, sql, args)) { s.executeUpdate(); }
    }

    static Actor authenticate(Connection c, String authorization) throws SQLException {
        if (authorization == null || !authorization.startsWith("Bearer ") || authorization.length() > 256) {
            throw new Policy.Rejected(401, "Member credential required");
        }
        try (PreparedStatement s = query(c, "SELECT m.id,m.name,coalesce(p.permission,CASE WHEN k.administrator THEN 'ADMINISTRATOR' ELSE 'MEMBER' END) FROM credentials k JOIN members m ON m.id=k.member_id LEFT JOIN member_permissions p ON p.member_id=m.id WHERE k.token_hash=? AND NOT k.revoked AND k.expires_at>now() AND m.active", Policy.hash(authorization.substring(7)));
             ResultSet r = s.executeQuery()) {
            if (!r.next()) throw new Policy.Rejected(401, "Invalid credential or inactive membership");
            return new Actor(r.getObject(1, UUID.class), r.getString(2), RankSecurity.Role.valueOf(r.getString(3)));
        }
    }

    static void lockMember(Connection c, UUID member) throws SQLException {
        try (PreparedStatement s = query(c, "SELECT active FROM members WHERE id=? FOR UPDATE", member); ResultSet r = s.executeQuery()) {
            if (!r.next() || !r.getBoolean(1)) throw new Policy.Rejected(403, "Active TRAP HOUSE membership required");
        }
    }

    static JsonObject event(Connection c, Actor actor, JsonObject body) throws SQLException {
        if (!Policy.normalize(Policy.text(body, "player", 12)).equals(Policy.normalize(actor.name))) {
            throw new Policy.Rejected(403, "Credential belongs to a different character");
        }
        UUID client = Policy.uuid(Policy.text(body, "id", 36));
        String type = Policy.text(body, "type", 12);
        Policy.observationType(type);
        String key = Policy.normalize(Policy.text(body, "key", 200));
        Instant observed = Policy.observed(Policy.text(body, "observedAt", 40), Instant.now());
        if (body.has("points")) throw new Policy.Rejected(400, "Points are calculated by the server");
        lockMember(c, actor.id);
        // Return the stored award for exact retries; unlocks additionally have a semantic unique index.
        try (PreparedStatement s = query(c, "SELECT id,points,type,event_key FROM events WHERE member_id=? AND client_id=?", actor.id, client); ResultSet r = s.executeQuery()) {
            if (r.next()) {
                if (!type.equals(r.getString(3)) || !key.equals(r.getString(4))) throw new Policy.Rejected(409, "Event ID reused with different evidence");
                return result(r.getObject(1).toString(), "DUPLICATE", r.getInt(2));
            }
        }
        int[] rule = rule(c, type, key);
        // A new request ID cannot repay the same collection unlock, even tomorrow.
        // Check before the daily cap so an already-paid pet is a clean duplicate.
        if(type.equals("COLLECTION")||type.equals("COMBAT")) {
            try(PreparedStatement s=query(c,"SELECT id FROM events WHERE member_id=? AND type=? AND event_key=?",actor.id,type,key);ResultSet r=s.executeQuery()) {
                if(r.next())return result(r.getString(1),"DUPLICATE",0);
            }
        }
        checkCap(c, actor.id, type, key, rule[1]);
        UUID id = UUID.randomUUID();
        int inserted;
        try (PreparedStatement s = query(c, "INSERT INTO events(id,member_id,client_id,type,event_key,observed_at,points) VALUES (?,?,?,?,?,?,?) ON CONFLICT DO NOTHING",
            id, actor.id, client, type, key, Timestamp.from(observed), rule[0])) { inserted = s.executeUpdate(); }
        if (inserted == 0) return result(client.toString(), "DUPLICATE", 0);
        award(c, actor, id, null, rule[0], type + ": " + key, category(c,type,key));
        ClanFeatures.updateEventGoals(c,actor);
        return result(id.toString(), "AWARDED", rule[0]);
    }

    static int[] rule(Connection c, String type, String key) throws SQLException {
        try (PreparedStatement s = query(c, "SELECT points,daily_limit FROM rules WHERE type=? AND event_key=? AND enabled", type, key); ResultSet r = s.executeQuery()) {
            if (!r.next()) throw new Policy.Rejected(422, "No enabled scoring rule for this observation");
            return new int[] {r.getInt(1), r.getInt(2)};
        }
    }

    static void checkCap(Connection c, UUID member, String type, String key, int limit) throws SQLException {
        String sharedItem=BalancedRewards.sharedItem(type,key);
        if(sharedItem!=null) {
            try(PreparedStatement s=query(c,"SELECT count(*) FROM events WHERE member_id=? AND type='LOOT' AND substring(event_key from '[^:]+$')=? AND received_at >= date_trunc('day',now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'",member,sharedItem);ResultSet r=s.executeQuery()) {
                r.next();if(r.getLong(1)>=limit)throw new Policy.Rejected(422,"Daily item reward limit reached across all sources");
            }
            if(BalancedRewards.barrows(type,key))try(PreparedStatement s=query(c,"SELECT count(*) FROM events WHERE member_id=? AND type='LOOT' AND event_key LIKE 'chest:barrows:%' AND received_at >= date_trunc('day',now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'",member);ResultSet r=s.executeQuery()) {
                r.next();if(r.getLong(1)>=BalancedRewards.BARROWS_DAILY_LIMIT)throw new Policy.Rejected(422,"Daily Barrows reward limit reached (four pieces total)");
            }
            return;
        }
        String sql = type.equals("MANUAL")
            ? "SELECT count(*) FROM manual_rewards WHERE member_id=? AND event_key=? AND status='APPROVED' AND reviewed_at >= date_trunc('day',now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'"
            : "SELECT count(*) FROM events WHERE member_id=? AND event_key=? AND type=? AND received_at >= date_trunc('day',now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'";
        try (PreparedStatement s = type.equals("MANUAL") ? query(c, sql, member, key) : query(c, sql, member, key, type); ResultSet r = s.executeQuery()) {
            r.next();
            if (r.getLong(1) >= limit) throw new Policy.Rejected(422, "Daily award limit reached");
        }
    }

    static JsonObject requestReward(Connection c, Actor actor, JsonObject body) throws SQLException {
        UUID request = Policy.uuid(Policy.text(body, "id", 36));
        String key = Policy.normalize(Policy.text(body, "key", 200));
        String reason = Policy.text(body, "reason", 1000);
        if (body.has("points") || body.has("memberId")) throw new Policy.Rejected(400, "Reward points and recipient are server controlled");
        lockMember(c, actor.id);
        try (PreparedStatement s = query(c, "SELECT id,points,status,event_key,reason FROM manual_rewards WHERE member_id=? AND request_id=?", actor.id, request); ResultSet r = s.executeQuery()) {
            if (r.next()) {
                if (!key.equals(r.getString(4)) || !reason.equals(r.getString(5))) throw new Policy.Rejected(409, "Request ID reused with different evidence");
                return result(r.getObject(1).toString(), r.getString(3), r.getInt(2));
            }
        }
        int[] rule = rule(c, "MANUAL", key);
        try (PreparedStatement s = query(c, "SELECT count(*) FROM manual_rewards WHERE member_id=? AND status='PENDING'", actor.id); ResultSet r = s.executeQuery()) {
            r.next();
            if (r.getLong(1) >= 20) throw new Policy.Rejected(422, "Too many pending rewards");
        }
        UUID id = UUID.randomUUID();
        execute(c, "INSERT INTO manual_rewards(id,member_id,request_id,event_key,reason,points,daily_limit) VALUES (?,?,?,?,?,?,?)", id, actor.id, request, key, reason, rule[0], rule[1]);
        execute(c, "INSERT INTO audit(actor,action,target) VALUES (?,'REWARD_REQUESTED',?)", actor.id, id);
        return result(id.toString(), "PENDING", rule[0]);
    }

    static JsonObject review(Connection c, Actor actor, UUID id, boolean approve) throws SQLException {
        if (!actor.admin) throw new Policy.Rejected(403, "Administrator required");
        try (PreparedStatement s = query(c, "SELECT member_id,event_key,points,status FROM manual_rewards WHERE id=? FOR UPDATE", id); ResultSet r = s.executeQuery()) {
            if (!r.next()) throw new Policy.Rejected(404, "Reward not found");
            UUID member = r.getObject(1, UUID.class);
            Policy.independentReviewer(actor.admin, actor.id, member);
            String key = r.getString(2);
            int points = r.getInt(3);
            String status = r.getString(4);
            if (!status.equals("PENDING")) return result(id.toString(), status, points);
            lockMember(c, member);
            if (approve) {
                int[] currentRule = rule(c, "MANUAL", key);
                // A rule change invalidates pending requests rather than silently changing the award.
                if (currentRule[0] != points) throw new Policy.Rejected(409, "Rule changed; reject and request again");
                checkCap(c, member, "MANUAL", key, currentRule[1]);
            }
            String state = approve ? "APPROVED" : "REJECTED";
            execute(c, "UPDATE manual_rewards SET status=?,reviewed_by=?,reviewed_at=now() WHERE id=?", state, actor.id, id);
            JsonObject reviewDetails=new JsonObject();
            reviewDetails.addProperty("memberId",member.toString());
            reviewDetails.addProperty("points",approve?points:0);
            reviewDetails.addProperty("key",key);
            RankSecurity.audit(c,actor,"REWARD_"+state,id,reviewDetails);
            if (approve) {
                String name;
                try (PreparedStatement m = query(c, "SELECT name FROM members WHERE id=?", member); ResultSet row = m.executeQuery()) { row.next(); name = row.getString(1); }
                Actor recipient = new Actor(member, name, false);
                award(c, recipient, null, id, points, "Approved reward: " + key, category(c,"MANUAL",key));
                ClanFeatures.updateEventGoals(c,recipient);
            }
            return result(id.toString(), state, points);
        }
    }

    static String category(Connection c,String type,String key) throws SQLException {
        try(PreparedStatement s=query(c,"SELECT category FROM rules WHERE type=? AND event_key=?",type,key);ResultSet r=s.executeQuery()) {
            if(r.next()&&java.util.Set.of("Drops","Pets","Milestones","Combat","Collection","Diaries","Challenges","Events","Misc").contains(r.getString(1)))return r.getString(1);
        }
        return type.equals("LOOT")?"Drops":type.equals("COMBAT")?"Combat":type.equals("COLLECTION")?"Collection":"Misc";
    }

    static void award(Connection c, Actor actor, UUID event, UUID reward, int points, String description,String category) throws SQLException {
        UUID ledger=UUID.randomUUID();
        execute(c, "INSERT INTO ledger(id,member_id,points,event_id,reward_id,category) VALUES (?,?,?,?,?,?)", ledger, actor.id, points, event, reward,category);
        execute(c,"INSERT INTO point_notifications(ledger_id,member_id,points,title) SELECT l.id,l.member_id,l.points,coalesce(nullif(rule.display_name,''),?) FROM ledger l LEFT JOIN events e ON e.id=l.event_id LEFT JOIN manual_rewards r ON r.id=l.reward_id LEFT JOIN rules rule ON rule.type=coalesce(e.type,'MANUAL') AND rule.event_key=coalesce(e.event_key,r.event_key) WHERE l.id=?",description,ledger);
        execute(c, "INSERT INTO discord_outbox(id,content) VALUES (?,?)", UUID.randomUUID(), actor.name + " earned " + points + " TRAP HOUSE points. " + description);
    }

    static JsonObject dashboard(Connection c, Actor actor, String player) throws SQLException {
        if (!Policy.normalize(actor.name).equals(Policy.normalize(player))) throw new Policy.Rejected(403, "Character mismatch");
        JsonObject data = new JsonObject();
        long points;
        try (PreparedStatement s = query(c, "SELECT coalesce(sum(points),0) FROM point_entries WHERE member_id=?", actor.id); ResultSet r = s.executeQuery()) { r.next(); points = r.getLong(1); }
        JsonObject profile = new JsonObject();
        profile.addProperty("name", actor.name);
        profile.addProperty("points", points);
        String rank = "Unranked", next = "Maximum rank reached";
        JsonArray ranks = new JsonArray();
        boolean foundNext = false;
        try (PreparedStatement s = query(c, "SELECT name,threshold FROM ranks WHERE name NOT IN (SELECT name FROM protected_ranks) AND name NOT IN (SELECT legacy_name FROM rank_aliases) ORDER BY threshold"); ResultSet r = s.executeQuery()) {
            while (r.next()) {
                JsonObject row = new JsonObject();
                row.addProperty("name", r.getString(1)); row.addProperty("threshold", r.getLong(2)); ranks.add(row);
                if (points >= r.getLong(2)) rank = r.getString(1);
                else if (!foundNext) { next = r.getString(1) + " at " + r.getLong(2) + " (" + (r.getLong(2) - points) + " remaining)"; foundNext = true; }
            }
        }
        profile.addProperty("rank", rank); profile.addProperty("nextThreshold", next);
        RankSecurity.enrich(c, actor.id, profile); profile.addProperty("permission",actor.role.name());
        data.add("profile", profile); data.add("ranks", ranks);
        JsonArray staffRanks=new JsonArray();
        try(PreparedStatement s=query(c,"SELECT name FROM protected_ranks WHERE name NOT IN (SELECT legacy_name FROM rank_aliases) ORDER BY CASE name WHEN 'Owner' THEN 0 WHEN 'Deputy Owner' THEN 1 WHEN 'Master' THEN 2 WHEN 'Major' THEN 3 WHEN 'Proselyte' THEN 4 ELSE 5 END,name");ResultSet r=s.executeQuery()) {
            while(r.next()){JsonObject row=new JsonObject();row.addProperty("name",r.getString(1));row.addProperty("protected",true);staffRanks.add(row);}
        }
        data.add("protectedRanks",staffRanks);
        if(actor.role==RankSecurity.Role.OWNER)data.add("rankManagement",RankManagement.read(c,actor));
        JsonArray leaders = new JsonArray();
        try (PreparedStatement s = query(c, "SELECT m.name,coalesce(sum(l.points),0) AS total,coalesce(labels.rank_name,s.assigned_rank),coalesce(s.locked,false),p.name IS NOT NULL,a.rank FROM members m LEFT JOIN point_entries l ON m.id=l.member_id LEFT JOIN member_rank_state s ON s.member_id=m.id LEFT JOIN rank_aliases labels ON labels.legacy_name=s.assigned_rank LEFT JOIN protected_ranks p ON p.name=coalesce(labels.rank_name,s.assigned_rank) LEFT JOIN retained_automatic_ranks a ON a.member_id=m.id WHERE m.active GROUP BY m.id,m.name,s.assigned_rank,labels.rank_name,s.locked,p.name,a.rank ORDER BY total DESC,m.normalized_name,m.id LIMIT 1000"); ResultSet r = s.executeQuery()) {
            while (r.next()) { JsonObject row = new JsonObject(); row.addProperty("name", r.getString(1)); row.addProperty("points", r.getLong(2)); String eligible="Unranked";for(JsonElement tier:ranks){if(tier.getAsJsonObject().get("threshold").getAsLong()<=r.getLong(2))eligible=tier.getAsJsonObject().get("name").getAsString();}eligible=r.getString(6)==null?eligible:r.getString(6);row.addProperty("automaticRank",eligible);row.addProperty("assignedRank",r.getString(3));row.addProperty("rankLocked",r.getBoolean(4));row.addProperty("protectedRank",r.getBoolean(5));row.addProperty("rank",r.getString(3)==null?eligible:r.getString(3));leaders.add(row); }
        }
        data.add("leaderboard", leaders);
        JsonArray sources = new JsonArray();
        try (PreparedStatement s = query(c, "SELECT type,event_key,points,daily_limit,display_name FROM rules WHERE enabled ORDER BY type,event_key LIMIT 1000"); ResultSet r = s.executeQuery()) {
            while (r.next()) { JsonObject row = new JsonObject(); row.addProperty("type", r.getString(1)); row.addProperty("key", r.getString(2)); row.addProperty("points", r.getInt(3)); row.addProperty("dailyLimit", r.getInt(4));row.addProperty("name",r.getString(5).isEmpty()?r.getString(2):r.getString(5)); sources.add(row); }
        }
        data.add("sources", sources);
        JsonArray history = new JsonArray();
        try (PreparedStatement s = query(c, "SELECT l.points,l.created_at,coalesce(e.type,CASE WHEN a.id IS NOT NULL THEN 'ADJUSTMENT' ELSE 'MANUAL' END),coalesce(g.name,e.event_key,r.event_key,a.reason) FROM point_entries l LEFT JOIN point_adjustments a ON a.id=l.id LEFT JOIN events e ON e.id=l.event_id LEFT JOIN manual_rewards r ON r.id=l.reward_id LEFT JOIN goals g ON e.type='GOAL' AND g.id::text=e.event_key WHERE l.member_id=? ORDER BY l.created_at DESC,l.id LIMIT 20", actor.id); ResultSet r = s.executeQuery()) {
            while (r.next()) { JsonObject row = new JsonObject(); row.addProperty("points", r.getInt(1)); row.addProperty("at", r.getTimestamp(2).toInstant().toString()); row.addProperty("type", r.getString(3)); row.addProperty("key", r.getString(4)); history.add(row); }
        }
        data.add("history", history);
        JsonArray rewards = new JsonArray();
        try (PreparedStatement s = query(c, "SELECT id,event_key,points,status FROM manual_rewards WHERE member_id=? ORDER BY requested_at DESC,id LIMIT 20", actor.id); ResultSet r = s.executeQuery()) {
            while (r.next()) { JsonObject row = new JsonObject(); row.addProperty("id", r.getString(1)); row.addProperty("key", r.getString(2)); row.addProperty("points", r.getInt(3)); row.addProperty("status", r.getString(4)); rewards.add(row); }
        }
        data.add("rewards", rewards);
        ClanFeatures.enrich(c,actor,data);
        return data;
    }

    static JsonArray pending(Connection c, Actor actor) throws SQLException {
        if (!actor.admin) throw new Policy.Rejected(403, "Administrator required");
        JsonArray rewards = new JsonArray();
        try (PreparedStatement s = query(c, "SELECT r.id,m.name,r.event_key,r.reason,r.points FROM manual_rewards r JOIN members m ON m.id=r.member_id WHERE r.status='PENDING' ORDER BY r.requested_at,r.id LIMIT 100"); ResultSet r = s.executeQuery()) {
            while (r.next()) { JsonObject row = new JsonObject(); row.addProperty("id", r.getString(1)); row.addProperty("name", r.getString(2)); row.addProperty("key", r.getString(3)); row.addProperty("reason", r.getString(4)); row.addProperty("points", r.getInt(5)); rewards.add(row); }
        }
        return rewards;
    }

    static JsonObject result(String id, String status, int points) {
        JsonObject result = new JsonObject();
        result.addProperty("id", id); result.addProperty("status", status); result.addProperty("points", points);
        return result;
    }
}

package com.traphouse.server;

import com.google.gson.*;
import java.sql.*;
import java.util.*;
import static com.traphouse.server.RankingStore.query;

/** Current enabled rewards with this member's confirmed award history. */
final class RewardCatalog {
    static JsonArray read(Connection c,UUID member,String category,String search,String sort)throws SQLException {
        List<JsonObject> cards=new ArrayList<>();
        if(category.equals("All")||category.equals("Drops"))
            for(JsonElement drop:PointsLog.dropRewards(c,member,search,sort))cards.add(drop.getAsJsonObject());
        if(!category.equals("Drops")) {
            String sql="WITH earned AS (SELECT coalesce(e.type,'MANUAL') AS type,coalesce(e.event_key,m.event_key) AS event_key,count(*) AS occurrences,sum(l.points) AS earned_points FROM ledger l LEFT JOIN events e ON e.id=l.event_id LEFT JOIN manual_rewards m ON m.id=l.reward_id WHERE l.member_id=? GROUP BY coalesce(e.type,'MANUAL'),coalesce(e.event_key,m.event_key)), catalog AS ("
                +"SELECT rule.type,coalesce(nullif(rule.display_name,''),rule.event_key) AS title,rule.points,rule.daily_limit,min(rule.event_key) AS source_key,coalesce(sum(earned.occurrences),0) AS received_count,coalesce(sum(earned.earned_points),0) AS earned_points,CASE WHEN rule.category<>'' THEN rule.category WHEN rule.type='LOOT' THEN 'Drops' WHEN rule.type='COMBAT' THEN 'Combat' WHEN rule.type='COLLECTION' THEN 'Collection' ELSE 'Misc' END AS category,false AS once_only,null::text AS item_id FROM rules rule LEFT JOIN earned ON earned.type=rule.type AND earned.event_key=rule.event_key WHERE rule.enabled AND rule.points>0 GROUP BY rule.type,coalesce(nullif(rule.display_name,''),rule.event_key),rule.points,rule.daily_limit,rule.category "
                +"UNION ALL SELECT 'GOAL',g.name,g.points,1,g.id::text,coalesce(earned.occurrences,0),coalesce(earned.earned_points,0),g.category,true,CASE WHEN g.source='ITEM' THEN g.source_key ELSE null END FROM goals g LEFT JOIN earned ON earned.type='GOAL' AND earned.event_key=g.id::text WHERE g.enabled AND g.points>0 AND g.source<>'MANUAL') "
                +"SELECT * FROM catalog WHERE category<>'Drops' AND (?='All' OR category=?) AND strpos(lower(title),lower(?))>0 ORDER BY title,type,source_key LIMIT 1000";
            try(PreparedStatement s=query(c,sql,member,category,category,search);ResultSet r=s.executeQuery()) {
                while(r.next()) {
                    JsonObject card=new JsonObject();
                    card.addProperty("sourceType",r.getString("type"));card.addProperty("title",r.getString("title"));
                    card.addProperty("points",r.getInt("points"));card.addProperty("dailyLimit",r.getInt("daily_limit"));
                    card.addProperty("sourceKey",r.getString("source_key"));card.addProperty("category",r.getString("category"));
                    int clueItem=EncounterRewards.clueItem(r.getString("type"),r.getString("source_key"));
                    if(clueItem>0)card.addProperty("itemId",clueItem);
                    if("LOOT".equals(r.getString("type")))card.addProperty("capScope",BalancedRewards.sharedItem("LOOT",r.getString("source_key"))==null?"source":"item");
                    long received=r.getLong("received_count");card.addProperty("receivedCount",received);card.addProperty("received",received>0);
                    card.addProperty("earnedPoints",r.getLong("earned_points"));
                    card.addProperty("onceOnly",r.getBoolean("once_only")||Arrays.asList("COMBAT","COLLECTION").contains(r.getString("type")));
                    String item=r.getString("item_id");
                    if(item!=null&&item.matches("[0-9]{1,6}"))card.addProperty("itemId",Integer.parseInt(item));
                    cards.add(card);
                }
            }
        }
        Comparator<JsonObject> byName=Comparator.comparing(e->e.get("title").getAsString(),String.CASE_INSENSITIVE_ORDER);
        cards.sort(sort.equals("highest")?Comparator.<JsonObject>comparingInt(e->e.get("points").getAsInt()).reversed().thenComparing(byName):byName);
        JsonArray result=new JsonArray();for(JsonObject card:cards)result.add(card);return result;
    }
}

package com.traphouse.server;

import java.net.URI;
import java.net.URLDecoder;
import java.nio.charset.StandardCharsets;
import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.SQLException;
import java.util.Map;
import java.util.Properties;

/** Environment configuration; connection strings and passwords must never be logged. */
final class ServerConfig {
    final String url;
    final Properties properties = new Properties();
    final String bindAddress;
    final int port;

    ServerConfig(Map<String, String> env) {
        bindAddress = env.getOrDefault("TRAP_BIND_ADDRESS", "127.0.0.1");
        try {
            port = Integer.parseInt(env.getOrDefault("PORT", env.getOrDefault("TRAP_PORT", "8090")));
            if (port < 1 || port > 65535) throw new NumberFormatException();
        } catch (NumberFormatException invalid) { throw new IllegalArgumentException("Invalid server port"); }
        String configured = required(env, "TRAP_DATABASE_URL");
        if (configured.startsWith("jdbc:postgresql:")) {
            url = configured;
            properties.setProperty("user", required(env, "TRAP_DATABASE_USER"));
            properties.setProperty("password", required(env, "TRAP_DATABASE_PASSWORD"));
        } else {
            try {
                URI uri = URI.create(configured);
                if (!("postgresql".equals(uri.getScheme()) || "postgres".equals(uri.getScheme()))
                    || uri.getHost() == null || uri.getRawUserInfo() == null
                    || uri.getRawPath() == null || uri.getRawPath().length() < 2 || uri.getFragment() != null)
                    throw new IllegalArgumentException();
                String[] credentials = uri.getRawUserInfo().split(":", 2);
                if (credentials.length != 2) throw new IllegalArgumentException();
                properties.setProperty("user", decode(credentials[0]));
                properties.setProperty("password", decode(credentials[1]));
                url = "jdbc:postgresql://" + uri.getHost() + (uri.getPort() < 0 ? "" : ":" + uri.getPort())
                    + uri.getRawPath() + (uri.getRawQuery() == null ? "" : "?" + uri.getRawQuery());
            } catch (IllegalArgumentException invalid) {
                throw new IllegalArgumentException("Invalid PostgreSQL connection configuration");
            }
        }
        properties.setProperty("connectTimeout", "5");
        properties.setProperty("socketTimeout", "15");
    }

    private static String decode(String value) {
        return URLDecoder.decode(value.replace("+", "%2B"), StandardCharsets.UTF_8);
    }

    private static String required(Map<String, String> env, String key) {
        String value = env.get(key);
        if (value == null || value.isEmpty()) throw new IllegalStateException("Missing environment variable: " + key);
        return value;
    }

    Connection connect() throws SQLException { return DriverManager.getConnection(url, properties); }
}

package com.traphouse.server;

import com.google.gson.*;
import java.net.*;
import java.net.http.*;
import java.nio.charset.StandardCharsets;
import java.sql.*;
import java.time.Duration;
import java.util.UUID;

/** Server-side public WOM import. Does not submit player updates or accept client efficiency values. */
final class WiseOldManStats implements Runnable {
    private final DiscordWorker.Connections connections;
    private final HttpClient http=HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(5)).followRedirects(HttpClient.Redirect.NEVER).build();
    WiseOldManStats(DiscordWorker.Connections connections){this.connections=connections;}
    static JsonObject parse(String response) {
        JsonObject data=JsonParser.parseString(response).getAsJsonObject(),result=new JsonObject();
        for(String metric:new String[]{"ehp","ehb"}) {
            if(!data.has(metric)||!data.get(metric).isJsonPrimitive()||!data.getAsJsonPrimitive(metric).isNumber())throw new IllegalArgumentException("Missing efficiency value");
            java.math.BigDecimal value=data.get(metric).getAsBigDecimal();
            if(value.signum()<0||value.compareTo(new java.math.BigDecimal("1000000000"))>0)throw new IllegalArgumentException("Efficiency value outside range");
            result.addProperty(metric,value);
        }
        if(data.has("updatedAt")&&!data.get("updatedAt").isJsonNull())result.addProperty("snapshotAt",java.time.Instant.parse(data.get("updatedAt").getAsString()).toString());
        return result;
    }
    @Override public void run() {
        UUID id;String name;
        try(Connection c=connections.open();PreparedStatement s=RankingStore.query(c,"SELECT m.id,m.name FROM members m LEFT JOIN member_metrics v ON v.member_id=m.id LEFT JOIN efficiency_reward_state e ON e.member_id=m.id LEFT JOIN metric_attempts a ON a.member_id=m.id WHERE m.active AND (v.fetched_at IS NULL OR v.fetched_at<now()-interval '1 hour' OR e.member_id IS NULL) AND (a.last_attempt IS NULL OR a.last_attempt<now()-interval '5 minutes') ORDER BY a.last_attempt NULLS FIRST,m.id LIMIT 1");ResultSet r=s.executeQuery()) {
            if(!r.next())return;id=r.getObject(1,UUID.class);name=r.getString(2);
            RankingStore.execute(c,"INSERT INTO metric_attempts(member_id) VALUES (?) ON CONFLICT(member_id) DO UPDATE SET last_attempt=now()",id);
        }catch(SQLException unavailable){return;}
        try {
            URI url=URI.create("https://api.wiseoldman.net/v2/players/"+URLEncoder.encode(name,StandardCharsets.UTF_8).replace("+","%20"));
            HttpRequest request=HttpRequest.newBuilder(url).timeout(Duration.ofSeconds(10)).header("User-Agent","TrapHouseRankings/1.0").GET().build();
            HttpResponse<java.io.InputStream> response=http.send(request,HttpResponse.BodyHandlers.ofInputStream());
            JsonObject values;
            try(java.io.InputStream input=response.body()) {
                if(response.statusCode()!=200)return;
                byte[] bytes=input.readNBytes(1_048_577);if(bytes.length>1_048_576)return;
                values=parse(new String(bytes,StandardCharsets.UTF_8));
            }
            try(Connection c=connections.open()) {
                c.setAutoCommit(false);
                try {
                    RankingStore.lockMember(c,id);
                    RankingStore.execute(c,"INSERT INTO member_metrics(member_id,ehp,ehb) VALUES (?,?,?) ON CONFLICT(member_id) DO UPDATE SET ehp=excluded.ehp,ehb=excluded.ehb,fetched_at=now()",id,values.get("ehp").getAsBigDecimal(),values.get("ehb").getAsBigDecimal());
                    EfficiencyRewards.observe(c,new RankingStore.Actor(id,name,false),values.get("ehp").getAsBigDecimal(),values.get("ehb").getAsBigDecimal(),
                        values.has("snapshotAt")?java.time.Instant.parse(values.get("snapshotAt").getAsString()):null,java.time.Instant.now());
                    c.commit();
                } catch(Exception failure){c.rollback();throw failure;}
            }
        }catch(InterruptedException stop){Thread.currentThread().interrupt();}
        catch(Exception failure){System.err.println("Public efficiency import unavailable; will retry.");}
    }
}

