package com.traphouse.server;

import java.lang.reflect.Proxy;
import java.sql.*;
import java.util.concurrent.atomic.AtomicInteger;
import org.junit.Test;
import static org.junit.Assert.*;

public class DatabaseInitializationTest {
    private Connection connection(AtomicInteger commits,AtomicInteger rollbacks,AtomicInteger closes) {
        return (Connection)Proxy.newProxyInstance(getClass().getClassLoader(),new Class<?>[]{Connection.class},(proxy,method,args)->{
            switch(method.getName()) {
                case "setAutoCommit":return null;
                case "commit":commits.incrementAndGet();return null;
                case "rollback":rollbacks.incrementAndGet();return null;
                case "close":closes.incrementAndGet();return null;
                case "prepareStatement":return Proxy.newProxyInstance(getClass().getClassLoader(),new Class<?>[]{PreparedStatement.class},(p,m,a)->{
                    if(m.getName().equals("executeUpdate"))return 0;
                    if(m.getName().equals("close"))return null;
                    throw new AssertionError(m.getName());
                });
                default:throw new AssertionError(method.getName());
            }
        });
    }
    @Test public void retriesOnlyTemporaryConflictsAndRollsBackBeforeReopening()throws Exception {
        AtomicInteger opens=new AtomicInteger(),commits=new AtomicInteger(),rollbacks=new AtomicInteger(),closes=new AtomicInteger();
        DatabaseInitialization.run(()->{opens.incrementAndGet();return connection(commits,rollbacks,closes);},c->{
            if(opens.get()<3)throw new SQLException("Temporary conflict",opens.get()==1?"40P01":"55P03");
        });
        assertEquals(3,opens.get());assertEquals(1,commits.get());assertEquals(2,rollbacks.get());assertEquals(3,closes.get());
        assertFalse(DatabaseInitialization.retryable(new SQLException("Invalid schema","42601")));
        assertFalse(DatabaseInitialization.retryable(new SQLException("Connection failed","08006")));
        assertTrue(DatabaseInitialization.retryable(new SQLException("Serialization conflict","40001")));
    }
    @Test public void permanentErrorsFailImmediatelyAndPersistentConflictsStopAfterFiveAttempts()throws Exception {
        for(String state:new String[]{"42601","40P01"}) {
            AtomicInteger opens=new AtomicInteger(),commits=new AtomicInteger(),rollbacks=new AtomicInteger(),closes=new AtomicInteger();
            try{DatabaseInitialization.run(()->{opens.incrementAndGet();return connection(commits,rollbacks,closes);},c->{throw new SQLException("Test failure",state);});fail("Expected failure");}
            catch(SQLException expected){assertEquals(state,expected.getSQLState());}
            assertEquals(state.equals("40P01")?5:1,opens.get());assertEquals(opens.get(),rollbacks.get());assertEquals(opens.get(),closes.get());assertEquals(0,commits.get());
        }
    }
}

package com.traphouse.server;

import com.google.gson.JsonObject;
import com.sun.net.httpserver.HttpServer;
import java.lang.reflect.Proxy;
import java.net.*;
import java.net.http.*;
import java.sql.*;
import java.util.*;
import org.junit.Test;
import static org.junit.Assert.*;

/** Real HTTP routing and token hashing with a credential-only JDBC fixture.
 * Any attempt to read or mutate a target member fails the test. */
public class DeductionHttpTest {
    private interface Call { Object invoke(String method,Object[] args) throws Throwable; }
    private static <T> T proxy(Class<T> type,Call call) {
        return type.cast(Proxy.newProxyInstance(type.getClassLoader(),new Class<?>[]{type},
            (object,method,args)->call.invoke(method.getName(),args)));
    }
    private Connection credentials(Map<String,RankingStore.Actor> identities) {
        return proxy(Connection.class,(method,args)-> {
            switch(method) {
                case "setAutoCommit":case "commit":case "rollback":case "close":return null;
                case "prepareStatement":
                    String sql=(String)args[0];Object[] parameter={null};
                    if(!sql.startsWith("SET LOCAL ")&&!sql.contains("FROM credentials k"))throw new AssertionError("Unauthorized target database access: "+sql);
                    return proxy(PreparedStatement.class,(operation,values)-> {
                        switch(operation) {
                            case "setObject":parameter[0]=values[1];return null;
                            case "close":return null;
                            case "executeUpdate":return 0;
                            case "executeQuery":
                                RankingStore.Actor actor=identities.get(parameter[0]);boolean[] read={false};
                                return proxy(ResultSet.class,(readMethod,columns)-> {
                                    switch(readMethod) {
                                        case "next":boolean found=!read[0]&&actor!=null;read[0]=true;return found;
                                        case "getObject":return actor.id;
                                        case "getString":return ((Integer)columns[0])==2?actor.name:actor.role.name();
                                        case "close":return null;
                                        default:throw new AssertionError(readMethod);
                                    }
                                });
                            default:throw new AssertionError(operation);
                        }
                    });
                default:throw new AssertionError(method);
            }
        });
    }
    @Test public void authenticatedNonOwnersCannotDeductThroughHttpOrSpoofOwnerFields() throws Exception {
        Map<String,RankingStore.Actor> identities=new HashMap<>();
        for(RankSecurity.Role role:RankSecurity.Role.values())identities.put(Policy.hash("token-"+role),new RankingStore.Actor(UUID.randomUUID(),role.name(),role));
        HttpServer server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);
        server.createContext("/",new RankingServer(()->credentials(identities))::handle);server.start();
        try {
            URI uri=URI.create("http://127.0.0.1:"+server.getAddress().getPort()+"/v1/admin/members/"+UUID.randomUUID()+"/points");
            JsonObject body=new JsonObject();body.addProperty("id",UUID.randomUUID().toString());body.addProperty("points",-50);body.addProperty("reason","Spoofed request");
            body.addProperty("permission","OWNER");body.addProperty("actor",identities.get(Policy.hash("token-OWNER")).id.toString());
            HttpClient http=HttpClient.newHttpClient();
            for(RankSecurity.Role role:RankSecurity.Role.values()) {
                if(role==RankSecurity.Role.OWNER)continue;
                HttpResponse<String> response=http.send(HttpRequest.newBuilder(uri).header("Authorization","Bearer token-"+role)
                    .header("Content-Type","application/json").POST(HttpRequest.BodyPublishers.ofString(body.toString())).build(),HttpResponse.BodyHandlers.ofString());
                assertEquals(role.name(),403,response.statusCode());
            }
            HttpResponse<String> unauthenticated=http.send(HttpRequest.newBuilder(uri).header("Authorization","Bearer invalid")
                .header("Content-Type","application/json").POST(HttpRequest.BodyPublishers.ofString(body.toString())).build(),HttpResponse.BodyHandlers.ofString());
            assertEquals(401,unauthenticated.statusCode());
        } finally { server.stop(0); }
    }
}

package com.traphouse.server;

import com.google.gson.*;
import com.sun.net.httpserver.HttpServer;
import java.lang.reflect.Proxy;
import java.net.*;
import java.net.http.*;
import java.nio.charset.StandardCharsets;
import java.security.*;
import java.sql.*;
import java.time.Instant;
import java.util.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class DiscordInteractionsTest {
    private static String hex(byte[] bytes){StringBuilder s=new StringBuilder();for(byte b:bytes)s.append(String.format("%02x",b&255));return s.toString();}
    private static String publicKey(KeyPair pair){byte[] encoded=pair.getPublic().getEncoded();return hex(Arrays.copyOfRange(encoded,encoded.length-32,encoded.length));}
    private static String sign(KeyPair pair,String timestamp,String body)throws Exception {
        Signature signature=Signature.getInstance("Ed25519");signature.initSign(pair.getPrivate());signature.update((timestamp+body).getBytes(StandardCharsets.UTF_8));return hex(signature.sign());
    }
    @Test public void rawBodySignaturesRejectForgeryTamperingAndStaleRequests()throws Exception {
        KeyPair pair=KeyPairGenerator.getInstance("Ed25519").generateKeyPair();Instant now=Instant.now();String timestamp=Long.toString(now.getEpochSecond()),body="{\"type\":1}";
        String signature=sign(pair,timestamp,body),key=publicKey(pair);
        assertTrue(DiscordInteractions.verify(key,signature,timestamp,body.getBytes(StandardCharsets.UTF_8),now));
        assertFalse(DiscordInteractions.verify(key,signature,timestamp,(body+" ").getBytes(StandardCharsets.UTF_8),now));
        assertFalse(DiscordInteractions.verify(key,signature,timestamp,body.getBytes(StandardCharsets.UTF_8),now.plusSeconds(301)));
        assertFalse(DiscordInteractions.verify(key,signature,timestamp,body.getBytes(StandardCharsets.UTF_8),now.minusSeconds(301)));
        assertFalse(DiscordInteractions.verify(key,"00".repeat(64),timestamp,body.getBytes(StandardCharsets.UTF_8),now));
        assertFalse(DiscordInteractions.verify(key,signature,"invalid",body.getBytes(StandardCharsets.UTF_8),now));
    }
    private interface Call {Object invoke(String method,Object[] args)throws Throwable;}
    private static <T>T proxy(Class<T> type,Call call){return type.cast(Proxy.newProxyInstance(type.getClassLoader(),new Class<?>[]{type},(object,method,args)->call.invoke(method.getName(),args)));}
    private static Connection nonOwnerOnly() {
        return proxy(Connection.class,(method,args)->{
            switch(method) {
                case "setAutoCommit":case "commit":case "rollback":case "close":return null;
                case "setSavepoint":return proxy(Savepoint.class,(op,values)->0);
                case "prepareStatement":
                    String sql=(String)args[0];
                    boolean cache=sql.startsWith("INSERT INTO discord_interactions")||sql.startsWith("UPDATE discord_interactions");
                    boolean owner=sql.startsWith("SELECT m.id,m.name FROM discord_member_links")&&sql.contains("p.permission='OWNER'")&&sql.contains("m.active");
                    boolean staff=sql.equals("SELECT member_id FROM discord_member_links WHERE discord_user_id=?");
                    if(!cache&&!owner&&!staff&&!sql.startsWith("SET LOCAL "))throw new AssertionError("Unauthorized target access: "+sql);
                    return proxy(PreparedStatement.class,(op,values)->{
                        switch(op){case "setObject":case "close":return null;case "executeUpdate":return 1;
                            case "executeQuery":return proxy(ResultSet.class,(read,cols)->{if(read.equals("next"))return false;if(read.equals("close"))return null;throw new AssertionError(read);});
                            default:throw new AssertionError(op);}
                    });
                default:throw new AssertionError(method);
            }
        });
    }
    @Test public void directSignedNonOwnerApprovalsCannotAccessRequestOrMembershipTables()throws Exception {
        KeyPair pair=KeyPairGenerator.getInstance("Ed25519").generateKeyPair();Map<String,String> env=new HashMap<>();
        env.put("TRAP_DISCORD_PUBLIC_KEY",publicKey(pair));env.put("TRAP_DISCORD_CLIENT_ID","111111111111111111");env.put("TRAP_DISCORD_GUILD_ID","222222222222222222");
        HttpServer server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);server.createContext("/",new DiscordInteractions(DiscordInteractionsTest::nonOwnerOnly,env)::handle);server.start();
        try {
            for(RankSecurity.Role role:RankSecurity.Role.values()) {
                if(role==RankSecurity.Role.OWNER)continue;
                for(String action:new String[]{"pending","edit-link","revoke-link","join:approve:","join:reject:","join:accept:","join:deny:","linked:edit:","linked:revoke:"}) {
                    int type=!action.contains(":")?2:(action.equals("join:approve:")||action.equals("join:reject:")?3:5);
                    JsonObject request=DiscordJoining.object("{\"id\":\"333333333333333333\",\"application_id\":\"111111111111111111\",\"guild_id\":\"222222222222222222\",\"member\":{\"user\":{\"id\":\"444444444444444444\"},\"roles\":[\"OWNER\"]},\"permission\":\"OWNER\"}");
                    request.addProperty("type",type);JsonObject data=new JsonObject();
                    if(type==2)data.addProperty("name",action);
                    else data.addProperty("custom_id",action+UUID.randomUUID());
                    if(type==5){JsonArray rows=new JsonArray();JsonObject input=new JsonObject();input.addProperty("custom_id","reason");input.addProperty("value","Forged Owner approval");rows.add(DiscordJoining.row(input));data.add("components",rows);}
                    data.addProperty("permission",role.name());request.add("data",data);
                    HttpResponse<String> response=post(server,pair,request.toString(),true);
                    assertEquals(200,response.statusCode());assertTrue(response.body(),response.body().contains("Only the linked clan Owner"));assertTrue(response.body().contains("64"));
                }
