package com.traphouse;

import com.google.gson.*;
import java.io.IOException;
import java.security.SecureRandom;
import java.util.Base64;
import java.util.concurrent.*;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.util.LinkBrowser;
import okhttp3.*;

/** Device authorization: the browser never sees the plugin credential or device secret. */
final class DiscordSignIn {
    private final OkHttpClient http;
    private final Gson gson;
    private final ConfigManager settings;
    private final ScheduledExecutorService executor;
    private ScheduledFuture<?> poll;
    private long revision;
    @Inject DiscordSignIn(OkHttpClient http,Gson gson,ConfigManager settings,ScheduledExecutorService executor) {
        this.http=http.newBuilder().followRedirects(false).followSslRedirects(false).callTimeout(20,TimeUnit.SECONDS).build();
        this.gson=gson;this.settings=settings;this.executor=executor;
    }
    synchronized void cancel(){revision++;if(poll!=null)poll.cancel(false);poll=null;}
    private synchronized boolean current(long epoch){return revision==epoch;}
    private static void report(Consumer<String> status,String message){SwingUtilities.invokeLater(()->status.accept(message));}
    void start(TrapHouseConfig config,Consumer<String> status) {
        cancel();final long epoch; synchronized(this){epoch=revision;}
        final String origin;
        try {origin=RankingClient.endpoint(config.rankingUrl().trim());}
        catch(IllegalArgumentException invalid){report(status,"Set a valid HTTPS ranking API address first.");return;}
        report(status,"Opening Discord sign-in…");
        executor.execute(()->{
            try {
                byte[] random=new byte[32];new SecureRandom().nextBytes(random);
                JsonObject request=new JsonObject();request.addProperty("secret",Base64.getUrlEncoder().withoutPadding().encodeToString(random));
                JsonObject session=post(origin+"/auth/discord/device",request);
                String url=session.get("url").getAsString();
                if(!validBrowserUrl(origin,url))throw new IOException("Invalid sign-in address");
                request.addProperty("session",session.get("session").getAsString());
                long deadline=System.nanoTime()+TimeUnit.MINUTES.toNanos(10);
                synchronized(this) {
                    if(!current(epoch))return;
                    SwingUtilities.invokeLater(()->{if(current(epoch))LinkBrowser.browse(url);});
                    poll=executor.scheduleWithFixedDelay(()->{
                        if(!current(epoch))return;
                        try {
                            if(System.nanoTime()>deadline)throw new IOException("Sign-in expired. Click Sign in with Discord to try again.");
                            JsonObject result=post(origin+"/auth/discord/poll",request);
                            if(!"complete".equals(result.get("status").getAsString()))return;
                            String token=result.get("token").getAsString();
                            if(!token.matches("[A-Za-z0-9_-]{43}"))throw new IOException("Invalid sign-in response");
                            synchronized(this) {
                                if(!current(epoch)||!origin.equals(RankingClient.endpoint(config.rankingUrl().trim())))return;
                                cancel();
                                settings.setConfiguration("traphouse","rankingToken",token);
                                settings.setConfiguration("traphouse","rankingEnabled",true);
                            }
                            report(status,"Connected. Log into your linked clan character to sync.");
                        } catch(Exception failure){if(current(epoch)){cancel();report(status,failure instanceof IOException?failure.getMessage():"Sign-in failed. Please try again.");}}
                    },5,5,TimeUnit.SECONDS);
                }
                report(status,"Finish signing in through your browser. First-time members need leadership to link their character.");
            } catch(Exception failure){if(current(epoch))report(status,failure instanceof IOException?failure.getMessage():"Sign-in failed. Please try again.");}
        });
    }
    static boolean validBrowserUrl(String origin,String url) {
        try {java.net.URI base=java.net.URI.create(origin), target=java.net.URI.create(url);
            return base.getScheme().equals(target.getScheme())&&base.getRawAuthority().equals(target.getRawAuthority())
                &&target.getUserInfo()==null&&target.getFragment()==null&&"/auth/discord/start".equals(target.getPath());
        } catch(IllegalArgumentException invalid){return false;}
    }
    private JsonObject post(String url,JsonObject body)throws IOException {
        try(Response response=http.newCall(new Request.Builder().url(url).post(RequestBody.create(MediaType.parse("application/json"),gson.toJson(body))).build()).execute()) {
            if(response.body()==null)throw new IOException("Sign-in server returned no response.");
            if(response.body().contentLength()>65536)throw new IOException("Invalid sign-in response.");
            try {
                byte[] bytes=response.body().byteStream().readNBytes(65537);
                if(bytes.length>65536)throw new IOException("Invalid sign-in response.");
                JsonObject result=gson.fromJson(new String(bytes,java.nio.charset.StandardCharsets.UTF_8),JsonObject.class);
                if(!response.isSuccessful())throw new IOException(response.code()==503?"Discord sign-in is not available yet. Ask leadership to check its Render setup.":"Sign-in expired or declined. Please try again.");
                return result;
            } catch(JsonParseException invalid){throw new IOException("Invalid sign-in response.");}
        }
    }
}

package com.traphouse;

import java.awt.Color;
import java.util.Locale;
import net.runelite.client.util.Text;

/** Colors the game's own reward notices without adding duplicate chat lines. */
final class DropChatColors {
    static String recolor(String message, TrapHouseConfig config) {
        if (!config.dropChatColors() || message == null) return null;
        String plain = Text.removeTags(message);
        Color color;
        if (plain.startsWith("You have a funny feeling like you're being followed")
            || plain.startsWith("You feel something weird sneaking into your backpack")
            || plain.startsWith("You have a funny feeling like you would have been followed")) {
            color = config.rankingPetMessageColor();
        } else if (plain.startsWith("New item added to your collection log:")) {
            color = config.rankingMilestoneMessageColor();
        } else if (plain.startsWith("Valuable drop:") || plain.startsWith("Untradeable drop:")
            || plain.startsWith("You received a drop:")) {
            color = config.rankingDropMessageColor();
        } else {
            return null;
        }
        if (color == null) return null;
        // Keep non-color markup (such as item images) intact.
        String content = message.replaceAll("(?i)</?col(?:=[^>]*)?>", "");
        return "<col=" + String.format(Locale.ROOT, "%06x", color.getRGB() & 0xffffff)
            + ">" + content + "</col>";
    }
}

package com.traphouse;

import java.time.Instant;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import net.runelite.client.util.Text;

/** Accessed on the client thread. Deduplicates alerts across refreshes and world hops. */
final class EventAlerts {
    private final Set<Integer> seen = new HashSet<>();
    private final Set<Integer> dayReminded = new HashSet<>();
    private final Set<Integer> hourReminded = new HashSet<>();
    private boolean initialized;

    void beginSession() { initialized = false; }

    List<String> poll(ClanEvent event, Instant now, boolean newEvents, boolean reminders) {
        List<String> messages = new ArrayList<>();
        boolean active = event != null && !now.isBefore(event.startsAt) && now.isBefore(event.endsAt);
        if (!initialized) {
            initialized = true;
            if (active) seen.add(event.id);
        }
        if (!active) return messages;
        String title = Text.removeTags(event.title) + " (" + EventSummary.target(event) + ")";
        if (seen.add(event.id) && newEvents) messages.add("New event started: " + title + ".");
        long seconds = java.time.Duration.between(now, event.endsAt).getSeconds();
        if (seconds <= 3600) {
            dayReminded.add(event.id);
            if (hourReminded.add(event.id) && reminders) messages.add(title + " ends in " + EventSummary.timing(event, now).replace(" left", "") + ".");
        } else if (seconds <= 86400 && dayReminded.add(event.id) && reminders) {
            messages.add(title + " ends in " + EventSummary.timing(event, now).replace(" left", "") + ".");
        }
        return messages;
    }
}

package com.traphouse;

import java.time.LocalTime;
import java.time.format.DateTimeFormatter;
import java.util.concurrent.Future;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import java.util.function.IntSupplier;
import javax.swing.SwingUtilities;

/** All state changes occur on Swing's event thread; HTTP work runs on the executor. */
final class EventLeaderboardController {
    private final WiseOldManClient client;
    private final ScheduledExecutorService executor;
    private final IntSupplier competitionId;
    private final boolean skillEvent;
    private TrapHousePanel panel;
    private Future<?> request;
    private volatile ClanEvent event;
    private volatile boolean checked;
    private boolean active = true;
    private long generation;
    private long lastRefresh;
    private String fetchedAt;
    private String playerName;

    EventLeaderboardController(WiseOldManClient client, ScheduledExecutorService executor, IntSupplier competitionId, boolean skillEvent) {
        this.client = client;
        this.executor = executor;
        this.competitionId = competitionId;
        this.skillEvent = skillEvent;
    }

    void setPanel(TrapHousePanel panel) {
        this.panel = panel;
        panel.updatePlayer(playerName);
        if (checked) panel.updateEvent(event, fetchedAt);
        if (request != null) panel.setLeaderboardLoading();
    }

    ClanEvent getEvent() { return event; }

    boolean isChecked() { return checked; }

    void updatePlayer(String name) {
        playerName = name;
        if (panel != null) panel.updatePlayer(name);
    }

    void refresh() {
        if (!active || request != null || panel == null) return;
        if (lastRefresh != 0 && System.nanoTime() - lastRefresh < TimeUnit.SECONDS.toNanos(30)) return;
        lastRefresh = System.nanoTime();
        long version = ++generation;
        panel.setLeaderboardLoading();
        int id = competitionId.getAsInt();
        request = executor.submit(() -> {
            try {
                ClanEvent fetched = client.fetchEvent(id, skillEvent);
                SwingUtilities.invokeLater(() -> received(version, fetched, null));
            } catch (Exception exception) {
                String error = exception instanceof java.io.IOException || exception instanceof IllegalArgumentException
                    ? exception.getMessage() : "Could not read Wise Old Man event scores.";
                SwingUtilities.invokeLater(() -> received(version, null, error));
            }
        });
    }

    private void received(long version, ClanEvent fetched, String error) {
        if (!active || version != generation) return;
        request = null;
        if (error != null) panel.setLeaderboardError(error);
        else {
            event = fetched;
            checked = true;
            fetchedAt = "Fetched " + LocalTime.now().format(DateTimeFormatter.ofPattern("HH:mm"));
            panel.updateEvent(event, fetchedAt);
        }
    }

    void reset() {
        ++generation;
        if (request != null) request.cancel(true);
        request = null;
        event = null;
        checked = false;
        lastRefresh = 0;
    }

    void stop() { active = false; reset(); panel = null; }
}

package com.traphouse;

import java.util.Locale;
import net.runelite.client.util.Text;

final class EventProgress {
    private EventProgress() { }

    static String describe(ClanEvent event, String player, boolean skill) {
        if (player == null || player.isEmpty()) return "Log in to see your event progress.";
        if (event == null) return "No event selected.";
        for (int index = 0; index < event.scores.size(); index++) {
            LeaderboardEntry entry = event.scores.get(index);
            if (!Text.standardize(entry.name.replace('_', ' ')).equals(Text.standardize(player.replace('_', ' ')))) continue;
            String unit = skill ? "XP" : "kills";
            String progress = String.format(Locale.US, "You: #%d / %,d %s gained", index + 1, entry.score, unit);
            if (index == 0) return progress + " / Leading!";
            long gap = event.scores.get(index - 1).score - entry.score;
            return progress + (gap == 0 ? " / Tied with the player above" : String.format(Locale.US, " / %,d %s behind #%d", gap, unit, index));
        }
        return "No recorded score for you in this event.";
    }
}

package com.traphouse;

import java.time.Duration;
import java.time.Instant;
import java.util.Locale;

final class EventSummary {
    private EventSummary() { }

    static String target(ClanEvent event) {
        String target = event.metric.replace('_', ' ');
        return target.isEmpty() ? target : target.substring(0, 1).toUpperCase(Locale.ROOT) + target.substring(1);
    }

    static String timing(ClanEvent event, Instant now) {
        if (!now.isBefore(event.endsAt)) return "Ended";
        boolean upcoming = now.isBefore(event.startsAt);
        long minutes = Math.max(1, (Duration.between(now, upcoming ? event.startsAt : event.endsAt).getSeconds() + 59) / 60);
        long days = minutes / 1440;
        long hours = minutes % 1440 / 60;
        String duration = days > 0 ? days + "d " + hours + "h"
            : hours > 0 ? hours + "h " + minutes % 60 + "m" : minutes + "m";
        return upcoming ? "Starts in " + duration : duration + " left";
    }
}

