    void setLeaderboardLoading() {
        refreshButton.setEnabled(false);
        setStatus("Refreshing Wise Old Man...");
    }

    void setLeaderboardError(String error) {
        refreshButton.setEnabled(true);
        setStatus(error + " Existing scores may be stale.");
    }

    void updateLeaderboard(List<LeaderboardEntry> scores, String fetchedAt) {
        renderScores(scores, "No scored participants yet");
        refreshButton.setEnabled(true);
        setStatus(fetchedAt + " / WOM snapshots");
    }

    void updateEvent(ClanEvent event, String fetchedAt) {
        currentEvent = event;
        openEventButton.setEnabled(event != null);
        openEventButton.setToolTipText(event == null ? "No event selected" : "https://wiseoldman.net/competitions/" + event.id);
        updatePlayer(playerName);
        if (event == null) {
            eventStatus.setText("");
            eventTitle.setFont(new Font("SansSerif", Font.BOLD, 16));
            eventTitle.setText(skillEvent ? "No active skill event" : "No active boss event");
            eventBoss.setText("Awaiting competition");
            eventDates.setText("");
            renderScores(Collections.emptyList(), skillEvent ? "No active skill event on Wise Old Man" : "No active boss event on Wise Old Man");
            refreshButton.setEnabled(true);
            setStatus("Group 2504 / checked for events");
        } else {
            Instant now = Instant.now();
            eventTitle.setFont(new Font("SansSerif", Font.BOLD, 17));
            eventStatus.setText(now.isBefore(event.startsAt) ? "UPCOMING EVENT" : !now.isBefore(event.endsAt) ? "ENDED EVENT" : "ACTIVE EVENT");
            eventTitle.setText(wrapped(event.title, 17, WHITE).getText());
            String boss = event.metric.replace('_', ' ');
            boss = Character.toUpperCase(boss.charAt(0)) + boss.substring(1);
            eventBoss.setText(wrapped(boss, 14, GOLD).getText());
            DateTimeFormatter dates = DateTimeFormatter.ofPattern("MMM d, HH:mm 'UTC'", Locale.US).withZone(ZoneOffset.UTC);
            eventDates.setText(wrapped(dates.format(event.startsAt) + " - " + dates.format(event.endsAt), 9, MUTED).getText());
            updateLeaderboard(event.scores, fetchedAt);
        }
        // Dynamic titles can wrap; release the event card's previous height.
        Container eventCard = eventTitle.getParent();
        eventCard.invalidate();
        ((JPanel) eventCard).setMaximumSize(new Dimension(Integer.MAX_VALUE, eventCard.getPreferredSize().height));
        invalidate();
        revalidate();
        repaint();
    }

    private void setStatus(String text) {
        leaderboardStatus.setText("<html><div style='width:126px'>" + text + "</div></html>");
        resizeLeaderboard();
    }

    void updatePlayer(String name) {
        playerName = name;
        personalProgress.setText(wrapped(EventProgress.describe(currentEvent, name, skillEvent), 10, GOLD).getText());
        resizeLeaderboard();
    }

    private void renderScores(List<LeaderboardEntry> scores, String emptyText) {
        leaderboardRows.removeAll();
        if (scores.isEmpty()) {
            leaderboardRows.add(wrapped(emptyText, 12, MUTED));
        } else {
            for (int index = 0; index < Math.min(10, scores.size()); index++) {
                LeaderboardEntry entry = scores.get(index);
                String score = skillEvent && entry.score >= 1000000 ? String.format(Locale.US, "%.1fM", entry.score / 1000000.0)
                    : skillEvent && entry.score >= 10000 ? String.format(Locale.US, "%.1fK", entry.score / 1000.0)
                    : String.format(Locale.US, "%,d", entry.score);
                JPanel row = leaderboardRow(index + 1, entry.name, score);
                row.setToolTipText(String.format(Locale.US, "%s: %,d %s gained", entry.name, entry.score, skillEvent ? "XP" : "kills"));
                leaderboardRows.add(row);
                gap(leaderboardRows, 10);
            }
        }
        resizeLeaderboard();
    }

    private void resizeLeaderboard() {
        leaderboardRows.invalidate();
        leaderboardRows.setMaximumSize(new Dimension(Integer.MAX_VALUE, leaderboardRows.getPreferredSize().height));
        leaderboardCard.invalidate();
        leaderboardCard.setMaximumSize(new Dimension(Integer.MAX_VALUE, leaderboardCard.getPreferredSize().height));
        invalidate();
        revalidate();
        repaint();
    }

    private JPanel leaderboardRow(int rank, String name, String kills) {
        Color color = rank == 1 ? GOLD : rank == 2 ? new Color(185, 197, 215) : rank == 3 ? new Color(207, 153, 120) : MUTED;
        JPanel row = new JPanel(new BorderLayout(8, 0));
        row.setOpaque(false);
        row.setAlignmentX(Component.LEFT_ALIGNMENT);
        row.add(label(String.format(Locale.US, "%02d", rank), 18, color), BorderLayout.WEST);
        JLabel player = label(name, 12, WHITE);
        player.putClientProperty("html.disable", Boolean.TRUE);
        player.setToolTipText(name);
        row.add(player, BorderLayout.CENTER);
        JPanel score = new JPanel();
        score.setOpaque(false);
        score.setLayout(new BoxLayout(score, BoxLayout.Y_AXIS));
        score.add(label(kills, 15, color));
        score.add(label(skillEvent ? "XP" : "KILLS", 8, MUTED));
        row.add(score, BorderLayout.EAST);
        row.setMaximumSize(new Dimension(Integer.MAX_VALUE, row.getPreferredSize().height));
        return row;
    }

    private void section(JPanel panel) {
        panel.setAlignmentX(Component.LEFT_ALIGNMENT);
        panel.setMaximumSize(new Dimension(Integer.MAX_VALUE, panel.getPreferredSize().height));
        add(panel);
        gap(this, 10);
    }

    private static void gap(JPanel panel, int height) { panel.add(Box.createVerticalStrut(height)); }

    private static JPanel card(boolean header) {
        JPanel panel = new Card(header);
        panel.setLayout(new BoxLayout(panel, BoxLayout.Y_AXIS));
        panel.setBorder(header ? new EmptyBorder(16, 14, 16, 14) : new EmptyBorder(13, 12, 13, 12));
        return panel;
    }

    private static JPanel prize(String rank, String name, int amount, Color color) {
        JPanel row = new JPanel(new BorderLayout(9, 0));
        row.setOpaque(false);
        row.setAlignmentX(Component.LEFT_ALIGNMENT);
        row.add(label(rank, 20, color), BorderLayout.WEST);
        JPanel detail = new JPanel();
        detail.setOpaque(false);
        detail.setLayout(new BoxLayout(detail, BoxLayout.Y_AXIS));
        detail.add(label(name, 9, MUTED));
        JLabel value = label(String.format(Locale.US, "%,d GP", amount), 13, WHITE);
        detail.add(value);
        row.setToolTipText(value.getText());
        row.add(detail, BorderLayout.CENTER);
        row.setMaximumSize(new Dimension(Integer.MAX_VALUE, row.getPreferredSize().height));
        return row;
    }

    private static JLabel wrapped(String text, int size, Color color) {
        String escaped = text == null ? "" : text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
        return label("<html><div style='width:126px'>" + escaped + "</div></html>", size, color);
    }

    private static JLabel label(String text, int size, Color color) {
        JLabel label = new JLabel(text);
        label.setFont(new Font("SansSerif", Font.BOLD, size));
        label.setForeground(color);
        label.setAlignmentX(Component.LEFT_ALIGNMENT);
        return label;
    }

    private static JButton button(String text, boolean primary) {
        JButton button = new JButton(text);
        button.setFont(new Font("SansSerif", Font.BOLD, 12));
        button.setForeground(primary ? WHITE : new Color(199, 206, 218));
        button.setBackground(primary ? new Color(167, 44, 59) : new Color(33, 37, 46));
        button.setFocusPainted(false);
        button.putClientProperty("JButton.buttonType", "roundRect");
        button.setAlignmentX(Component.LEFT_ALIGNMENT);
        button.setMaximumSize(new Dimension(Integer.MAX_VALUE, 34));
        button.setPreferredSize(new Dimension(180, 34));
        return button;
    }

    private JButton linkButton(String text, String url, boolean primary) {
        JButton button = button(text, primary);
        button.setEnabled(url != null && url.matches("https://.+"));
        if (!button.isEnabled()) button.setToolTipText("Community link coming soon");
        button.addActionListener(e -> LinkBrowser.browse(url));
        return button;
    }
    static class Card extends JPanel {
        private final boolean header;
        Card(boolean header) { this.header = header; setOpaque(false); }
        @Override protected void paintComponent(Graphics graphics) {
            Graphics2D g = (Graphics2D) graphics.create();
            g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            if (header) g.setPaint(new GradientPaint(0, 0, new Color(85, 27, 40), getWidth(), getHeight(), new Color(29, 24, 34)));
            else g.setColor(new Color(24, 27, 34));
            g.fillRoundRect(0, 0, getWidth() - 1, getHeight() - 1, 16, 16);
            g.setColor(header ? new Color(120, 48, 61) : new Color(43, 47, 57));
            g.drawRoundRect(0, 0, getWidth() - 1, getHeight() - 1, 16, 16);
            if (header) { g.setColor(RED); g.fillRoundRect(getWidth() - 35, 18, 20, 3, 3, 3); }
            g.dispose();
            super.paintComponent(graphics);
        }
    }
}

package com.traphouse;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Locale;
import java.util.concurrent.TimeUnit;
import java.time.Instant;
import net.runelite.client.hiscore.HiscoreSkill;
import net.runelite.client.hiscore.HiscoreSkillType;
import javax.inject.Inject;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;

final class WiseOldManClient {
    static final int GROUP_ID = 2504;
    private final OkHttpClient http;
    private final Gson gson;
    private JsonArray cachedCompetitions;
    private long competitionsFetched;

    @Inject
    WiseOldManClient(OkHttpClient http, Gson gson) {
        this.http = http.newBuilder().callTimeout(20, TimeUnit.SECONDS).build();
        this.gson = gson;
    }

    static String metric(String boss) {
        if (boss == null) throw new IllegalArgumentException("Choose a boss in plugin settings.");
        String metric = boss.trim().toLowerCase(Locale.ROOT).replace("'", "").replace("\u2019", "")
            .replaceAll("[^a-z0-9]+", "_").replaceAll("^_|_$", "");
        if (metric.isEmpty()) throw new IllegalArgumentException("Choose a boss in plugin settings.");
        return metric;
    }

    /** Runs on a background executor. A null result means no active boss event exists. */
    ClanEvent fetchEvent(int competitionId) throws IOException {
        return fetchEvent(competitionId, false);
    }

    ClanEvent fetchEvent(int competitionId, boolean skillEvent) throws IOException {
        if (competitionId <= 0) {
            competitionId = selectCurrentEvent(competitions(), Instant.now(), skillEvent);
            if (competitionId == 0) return null;
        }
        return parseEvent(getJson("competitions/" + competitionId), gson, skillEvent);
    }

    private synchronized JsonArray competitions() throws IOException {
        if (cachedCompetitions == null || System.nanoTime() - competitionsFetched > TimeUnit.SECONDS.toNanos(30)) {
            cachedCompetitions = gson.fromJson(getJson("groups/" + GROUP_ID + "/competitions"), JsonArray.class);
            competitionsFetched = System.nanoTime();
        }
        return cachedCompetitions;
    }

    private String getJson(String path) throws IOException {
        Request request = new Request.Builder().url("https://api.wiseoldman.net/v2/" + path)
            .header("User-Agent", "TrapHouseRuneLite/1.0 (Wise Old Man group 2504)")
            .header("Accept", "application/json").build();
        try (Response response = http.newCall(request).execute()) {
            if (!response.isSuccessful()) {
                throw new IOException(response.code() == 429 ? "Rate limited. Please wait before refreshing."
                    : "Wise Old Man returned HTTP " + response.code() + ". Check the competition ID.");
            }
            if (response.body() == null) throw new IOException("Wise Old Man returned an empty response.");
            return response.body().string();
        }
    }

    static boolean isBossMetric(String metric) {
        for (HiscoreSkill skill : HiscoreSkill.values()) {
            if (skill.getType() == HiscoreSkillType.BOSS && metric(skill.getName()).equals(metric)) return true;
        }
        // Wise Old Man calls the three Moons of Peril bosses Lunar Chests.
        return "lunar_chests".equals(metric);
    }

    static int selectCurrentEvent(JsonArray events, Instant now) {
        return selectCurrentEvent(events, now, false);
    }

    static boolean isSkillMetric(String metric) {
        for (HiscoreSkill skill : HiscoreSkill.values()) {
            if (skill.getType() == HiscoreSkillType.SKILL && !"overall".equals(metric)
                && metric(skill.getName()).equals(metric)) return true;
        }
        return false;
    }

    static int selectCurrentEvent(JsonArray events, Instant now, boolean skillEvent) {
        int id = 0;
        Instant latestStart = Instant.MIN;
        for (JsonElement element : events) {
            JsonObject event = element.getAsJsonObject();
            String metric = event.get("metric").getAsString();
            if (!(skillEvent ? isSkillMetric(metric) : isBossMetric(metric))) continue;
            Instant start = Instant.parse(event.get("startsAt").getAsString());
            Instant end = Instant.parse(event.get("endsAt").getAsString());
            if (!now.isBefore(start) && now.isBefore(end) && start.isAfter(latestStart)) {
                id = event.get("id").getAsInt();
                latestStart = start;
            }
        }
        return id;
    }

    static ClanEvent parseEvent(String json, Gson gson) {
        return parseEvent(json, gson, false);
    }

    static ClanEvent parseEvent(String json, Gson gson, boolean skillEvent) {
        JsonObject event = gson.fromJson(json, JsonObject.class);
        if (event.get("groupId") == null || event.get("groupId").isJsonNull()
            || event.get("groupId").getAsInt() != GROUP_ID) {
            throw new IllegalArgumentException("Competition must belong to Trap House group 2504.");
        }
        String metric = event.get("metric").getAsString();
        if (!(skillEvent ? isSkillMetric(metric) : isBossMetric(metric))) {
            throw new IllegalArgumentException(skillEvent ? "Choose a single-skill competition for Skill of the Month."
                : "Choose a boss competition for the boss event tab.");
        }
        List<LeaderboardEntry> scores = new ArrayList<>();
        for (JsonElement element : event.getAsJsonArray("participations")) {
            JsonObject participation = element.getAsJsonObject();
            JsonObject progress = participation.getAsJsonObject("progress");
            if (progress == null || progress.get("gained").isJsonNull()) continue;
            long gained = progress.get("gained").getAsLong();
            // Do not treat missing hiscores baselines as an earned score.
            if (gained < 0 || progress.get("start").getAsLong() < 0 || progress.get("end").getAsLong() < 0) continue;
            JsonObject player = participation.getAsJsonObject("player");
            JsonElement displayName = player.get("displayName");
            String name = displayName == null || displayName.isJsonNull()
                ? player.get("username").getAsString() : displayName.getAsString();
            scores.add(new LeaderboardEntry(name, gained));
        }
        scores.sort(Comparator.comparingLong((LeaderboardEntry entry) -> entry.score).reversed()
            .thenComparing(entry -> entry.name, String.CASE_INSENSITIVE_ORDER));
        return new ClanEvent(event.get("id").getAsInt(), event.get("title").getAsString(), metric,
            Instant.parse(event.get("startsAt").getAsString()), Instant.parse(event.get("endsAt").getAsString()),
            scores);
    }

}

package com.traphouse;

import com.google.gson.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class AwardItemImagesTest {
    @Test public void existingPetReceiptsUseCanonicalInGamePetSprites() {
        assertEquals(12655,AwardItemImages.itemId(entry("{sourceType:'COLLECTION',sourceKey:'pet kraken',category:'Pets'}")));
        assertEquals(27352,AwardItemImages.itemId(entry("{sourceType:'COLLECTION',sourceKey:\"tumeken's guardian\",category:'Pets'}")));
    }
